        public string SchemaLabel_Mpv_ad_lavc_ac3drc { get; set; } = "AC-3 dynamic range compression";
        public string SchemaDesc_Mpv_ad_lavc_ac3drc { get; set; } = "Select the Dynamic Range Compression level for AC-3 audio streams. <level> is a float value ranging from 0 to 1, where 0 means no compression (which is the default) and 1 means full compression (make loud passages more silent and vice versa). Values up to 6 are also accepted, but are purely experimental. This option only shows an effect if the AC-3 stream contains the required range compression information.";
        public string SchemaLabel_Mpv_ad_lavc_threads { get; set; } = "Audio decoder threads";
        public string SchemaDesc_Mpv_ad_lavc_threads { get; set; } = "Number of threads to use for decoding. Whether threading is actually supported depends on codec. As of this writing, it's supported for some lossless codecs only. 0 means autodetect number of cores on the machine and use that, up to the maximum of 16 (default: 1).";
        public string SchemaLabel_Mpv_ad_queue_enable { get; set; } = "Decode on a separate thread";
        public string SchemaDesc_Mpv_ad_queue_enable { get; set; } = "Enable running the video/audio decoder on a separate thread (default: no). If enabled, the decoder is run on a separate thread, and a frame queue is put between decoder and higher level playback logic. The size of the frame queue is defined by the other options below.";
        public string SchemaLabel_Mpv_ad_queue_max_bytes { get; set; } = "Queue memory limit";
        public string SchemaDesc_Mpv_ad_queue_max_bytes { get; set; } = "Maximum approximate allowed size of the queue. If exceeded, decoding will be stopped. The maximum size can be exceeded by about 1 frame.";
        public string SchemaLabel_Mpv_ad_queue_max_samples { get; set; } = "Queue sample limit";
        public string SchemaDesc_Mpv_ad_queue_max_samples { get; set; } = "Maximum number of frames (video) or samples (audio) of the queue. The audio size may be exceeded by about 1 frame.";
        public string SchemaLabel_Mpv_ad_queue_max_secs { get; set; } = "Queue duration limit";
        public string SchemaDesc_Mpv_ad_queue_max_secs { get; set; } = "Maximum number of seconds of media in the queue. The special value 0 means no limit is set. The queue size may be exceeded by about 2 frames. Timestamp resets may lead to random queue size usage.";
        public string SchemaLabel_Mpv_aid { get; set; } = "Audio track";
        public string SchemaDesc_Mpv_aid { get; set; } = "Select audio track. auto selects the default, no disables audio. See also --alang. mpv normally prints available audio tracks on the terminal when starting playback of a file.";
        public string SchemaLabel_Mpv_allow_delayed_peak_detect { get; set; } = "Delay peak detection";
        public string SchemaDesc_Mpv_allow_delayed_peak_detect { get; set; } = "When using --hdr-compute-peak, allow delaying the detected peak by a frame when beneficial for performance. In particular, this is required to avoid an unnecessary FBO indirection when no advanced rendering is required otherwise. Has no effect if there already is an indirect pass, such as when advanced scaling is enabled. Defaults to no. (Only affects --vo=gpu-next, note that --vo=gpu always delays the peak.)";
        public string SchemaLabel_Mpv_archive_exts { get; set; } = "Archive extensions";
        public string SchemaDesc_Mpv_archive_exts { get; set; } = "Archive file extensions to try to match when using --autocreate-playlist or --directory-filter-types.";
        public string SchemaLabel_Mpv_audio_client_name { get; set; } = "Reported application name";
        public string SchemaDesc_Mpv_audio_client_name { get; set; } = "The application name the player reports to the audio API. Can be useful if you want to force a different audio profile (e.g. with PulseAudio), or to set your own application name when using libmpv.";
        public string SchemaLabel_Mpv_audio_demuxer { get; set; } = "External audio demuxer";
        public string SchemaDesc_Mpv_audio_demuxer { get; set; } = "Use this audio demuxer type when using --audio-file. Use a '+' before the name to force it; this will skip some checks. Give the demuxer name as printed by --audio-demuxer=help.";
        public string SchemaLabel_Mpv_audio_fallback_to_null { get; set; } = "Silent fallback output";
        public string SchemaDesc_Mpv_audio_fallback_to_null { get; set; } = "If no audio device can be opened, behave as if --ao=null was given. This is useful in combination with --audio-device: instead of causing an error if the selected device does not exist, the client API user (or a Lua script) could let playback continue normally, and check the current-ao and audio-device-list properties to make high-level decisions about how to continue.";
        public string SchemaLabel_Mpv_audio_files { get; set; } = "External audio files";
        public string SchemaDesc_Mpv_audio_files { get; set; } = "Play audio from an external file while viewing a video.";
        public string SchemaLabel_Mpv_audio_resample_cutoff { get; set; } = "Resampler cutoff";
        public string SchemaDesc_Mpv_audio_resample_cutoff { get; set; } = "Cutoff frequency (0.0-1.0), default set depending upon filter length.";
        public string SchemaLabel_Mpv_audio_resample_filter_size { get; set; } = "Resampler filter length";
        public string SchemaDesc_Mpv_audio_resample_filter_size { get; set; } = "Length of the filter with respect to the lower sampling rate. (default: 16)";
        public string SchemaLabel_Mpv_audio_resample_linear { get; set; } = "Linear interpolate filter";
        public string SchemaDesc_Mpv_audio_resample_linear { get; set; } = "If set then filters will be linearly interpolated between polyphase entries. (default: no)";
        public string SchemaLabel_Mpv_audio_resample_max_output_size { get; set; } = "Resampler frame limit";
        public string SchemaDesc_Mpv_audio_resample_max_output_size { get; set; } = "Limit maximum size of audio frames filtered at once, in ms (default: 40). The output size is limited in order to make resample speed changes react faster. This is necessary especially if decoders or filters output very large frame sizes (like some lossless codecs or some DRC filters). This option does not affect the resampling algorithm in any way.";
        public string SchemaLabel_Mpv_audio_resample_phase_shift { get; set; } = "Resampler phase count";
        public string SchemaDesc_Mpv_audio_resample_phase_shift { get; set; } = "Log2 of the number of polyphase entries. (..., 10->1024, 11->2048, 12->4096, ...) (default: 10->1024)";
        public string SchemaLabel_Mpv_audio_set_media_role { get; set; } = "Report media role";
        public string SchemaDesc_Mpv_audio_set_media_role { get; set; } = "If enabled, mpv will set the appropriate media role on supported audio servers to indicate whether mpv is playing a video or an audio-only file. This is disabled by default since per media role volumes have often caused unexpected and confusing behavior.";
        public string SchemaLabel_Mpv_autofit { get; set; } = "Initial window size cap";
        public string SchemaDesc_Mpv_autofit { get; set; } = "Set the initial window size to a maximum size specified by WxH, without changing the window's aspect ratio. The size is measured in pixels, or if a number is followed by a percentage sign (%), in percents of the screen size.";
        public string SchemaLabel_Mpv_autofit_larger { get; set; } = "Window maximum size";
        public string SchemaDesc_Mpv_autofit_larger { get; set; } = "This option behaves exactly like --autofit, except that it sets the maximum size of the window.";
        public string SchemaLabel_Mpv_autofit_smaller { get; set; } = "Window minimum size";
        public string SchemaDesc_Mpv_autofit_smaller { get; set; } = "This option behaves exactly like --autofit, except that it sets the minimum size of the window (just as --autofit-larger sets the maximum).";
        public string SchemaLabel_Mpv_autoload_files { get; set; } = "Auto-load side files";
        public string SchemaDesc_Mpv_autoload_files { get; set; } = "Automatically load/select external files (default: yes).";
        public string SchemaLabel_Mpv_autosync { get; set; } = "Automatic A/V sync";
        public string SchemaDesc_Mpv_autosync { get; set; } = "Gradually adjusts the A/V sync based on audio delay measurements. Specifying --autosync=0, the default, will cause frame timing to be based entirely on audio delay measurements. Specifying --autosync=1 will do the same, but will subtly change the A/V correction algorithm. An uneven video framerate in a video which plays fine with --audio=no can often be helped by setting this to an integer value greater than 1. The higher the value, the closer the timing will be to --audio=no. Try --autosync=30 to smooth out problems with sound drivers which do not implement a perfect audio delay measurement. With this value, if large A/V sync offsets occur, they will only take about 1 or 2 seconds to settle out. This delay in reaction time to sudden A/V offsets should be the only side effect of turning this option on, for all sound drivers.";
        public string SchemaLabel_Mpv_backdrop_type { get; set; } = "Window backdrop material";
        public string SchemaDesc_Mpv_backdrop_type { get; set; } = "(Windows only) Controls the backdrop/border style.";
        public string SchemaLabel_Mpv_background { get; set; } = "Alpha background";
        public string SchemaDesc_Mpv_background { get; set; } = "If the frame has an alpha component, decide what kind of background, if any, to blend it with. This does nothing if there is no alpha component.";
        public string SchemaLabel_Mpv_background_blur_radius { get; set; } = "Background blur radius";
        public string SchemaDesc_Mpv_background_blur_radius { get; set; } = "The blur radius (in pixels) to use for --border-background=blur";
        public string SchemaLabel_Mpv_background_color { get; set; } = "Background color";
        public string SchemaDesc_Mpv_background_color { get; set; } = "Color used to draw parts of the mpv window not covered by video in --background=color mode. See the --sub-color option for how colors are defined.";
        public string SchemaLabel_Mpv_bluray_angle { get; set; } = "Blu-ray angle";
        public string SchemaDesc_Mpv_bluray_angle { get; set; } = "Some Blu-ray discs contain scenes that can be viewed from multiple angles. This option tells mpv which angle to use (default: 1).";
        public string SchemaLabel_Mpv_bluray_device { get; set; } = "Blu-ray disc path";
        public string SchemaDesc_Mpv_bluray_device { get; set; } = "Specify the Blu-ray disc location. Must be a directory with Blu-ray structure. The default device path depends on the OS. See the OPTICAL DRIVES section.";
        public string SchemaLabel_Mpv_border_background { get; set; } = "Border area background";
        public string SchemaDesc_Mpv_border_background { get; set; } = "Same as --background but only applies to the black bar/border area of the window. vo=gpu-next only. Defaults to color.";
        public string SchemaLabel_Mpv_chapter_merge_threshold { get; set; } = "Chapter merge threshold";
        public string SchemaDesc_Mpv_chapter_merge_threshold { get; set; } = "Threshold for merging almost consecutive ordered chapter parts in milliseconds (default: 100). Some Matroska files with ordered chapters have inaccurate chapter end timestamps, causing a small gap between the end of one chapter and the start of the next one when they should match. If the end of one playback part is less than the given threshold away from the start of the next one then keep playing video normally over the chapter change instead of doing a seek.";
        public string SchemaLabel_Mpv_chapter_seek_threshold { get; set; } = "Previous chapter threshold";
        public string SchemaDesc_Mpv_chapter_seek_threshold { get; set; } = "Distance in seconds from the beginning of a chapter within which a backward chapter seek will go to the previous chapter (default: 5.0). Past this threshold, a backward chapter seek will go to the beginning of the current chapter instead. A negative value means always go back to the previous chapter.";
        public string SchemaLabel_Mpv_chapters_file { get; set; } = "External chapters file";
        public string SchemaDesc_Mpv_chapters_file { get; set; } = "Load chapters from this file, instead of using the chapter metadata found in the main file.";
        public string SchemaLabel_Mpv_clipboard_backends { get; set; } = "Clipboard backends";
        public string SchemaDesc_Mpv_clipboard_backends { get; set; } = "Specify a priority list of the clipboard backends to be used. You can also pass help to get a complete list of compiled in backends.";
        public string SchemaLabel_Mpv_clipboard_monitor { get; set; } = "Watch clipboard changes";
        public string SchemaDesc_Mpv_clipboard_monitor { get; set; } = "Enable clipboard monitoring so that the clipboard property can be observed for content changes (default: no). This only affects clipboard implementations which use polling to monitor clipboard updates. Other platforms currently ignore this option and always/never notify changes.";
        public string SchemaLabel_Mpv_config { get; set; } = "Read config files";
        public string SchemaDesc_Mpv_config { get; set; } = "Flag; Default: yes";
        public string SchemaLabel_Mpv_container_fps_override { get; set; } = "Override frame rate";
        public string SchemaDesc_Mpv_container_fps_override { get; set; } = "Override video framerate. Useful if the original value is wrong or missing.";
        public string SchemaLabel_Mpv_cookies { get; set; } = "Send cookies";
        public string SchemaDesc_Mpv_cookies { get; set; } = "Support cookies when making HTTP requests. Disabled by default.";
        public string SchemaLabel_Mpv_corner_rounding { get; set; } = "Rounded video corners";
        public string SchemaDesc_Mpv_corner_rounding { get; set; } = "If set to a value above 0.0, the output will be rendered with rounded corners, as if an alpha transparency mask had been applied. The value indicates the relative fraction of the side length to round - a value of 1.0 rounds the corners as much as possible. (--vo=gpu-next only)";
        public string SchemaLabel_Mpv_correct_pts { get; set; } = "Correct timestamps";
        public string SchemaDesc_Mpv_correct_pts { get; set; } = "--correct-pts=no switches mpv to a mode where video timing is determined using a fixed framerate value (either using the --container-fps-override option, or using file information). Sometimes, files with very broken timestamps can be played somewhat well in this mode. Note that video filters, subtitle rendering, seeking (including hr-seeks and backstepping), and audio synchronization can be completely broken in this mode.";
        public string SchemaLabel_Mpv_cover_art_auto { get; set; } = "Load external cover art";
        public string SchemaDesc_Mpv_cover_art_auto { get; set; } = "Whether to load _external_ cover art automatically. Similar to --sub-auto and --audio-file-auto. If a video already has tracks (which are not marked as cover art), external cover art will not be loaded.";
        public string SchemaLabel_Mpv_cover_art_files { get; set; } = "Cover art file";
        public string SchemaDesc_Mpv_cover_art_files { get; set; } = "Use an external file as cover art while playing audio. This makes it appear on the track list and subject to automatic track selection. Options like --audio-display control whether such tracks are supposed to be selected.";
        public string SchemaLabel_Mpv_cover_art_whitelist { get; set; } = "Cover art filenames";
        public string SchemaDesc_Mpv_cover_art_whitelist { get; set; } = "Filenames to load as cover art, sorted by descending priority. They are combined with the extensions in --image-exts. This has no effect if cover-art-auto is no.";
        public string SchemaLabel_Mpv_curl_enabled { get; set; } = "libcurl network backend";
        public string SchemaDesc_Mpv_curl_enabled { get; set; } = "Enable the libcurl-based network backend (default: yes).";
        public string SchemaLabel_Mpv_curl_http_version { get; set; } = "HTTP protocol version";
        public string SchemaDesc_Mpv_curl_http_version { get; set; } = "Select the maximum HTTP protocol version libcurl is allowed to negotiate. (default: auto, i.e. let libcurl pick)";
        public string SchemaLabel_Mpv_d3d11_composition_size { get; set; } = "D3D11 composition size";
        public string SchemaDesc_Mpv_d3d11_composition_size { get; set; } = "Set size of the output for d3d11 composition mode. When use composition mode, there is no window, must set the output size by the embedding application.";
        public string SchemaLabel_Mpv_d3d11_feature_level { get; set; } = "D3D11 feature level";
        public string SchemaDesc_Mpv_d3d11_feature_level { get; set; } = "Select a specific feature level when using the D3D11 GPU backend. By default, the highest available feature level is used. This option can be used to select a lower feature level, which is mainly useful for debugging. Most extended GPU features will not work at 9_x feature levels.";
        public string SchemaLabel_Mpv_d3d11_output_mode { get; set; } = "D3D11 output mode";
        public string SchemaDesc_Mpv_d3d11_output_mode { get; set; } = "Use a specific output mode for creating the D3D11 swapchain. \"composition\" will not create a window. If you want to use the D3D11 GPU backend in WinUI applications, you need to set this to \"composition\". \"window\" will create a window and use the DWM to present the video. \"auto\" is the same as \"window\". After creating the swapchain, you can get the swapchain address (int64 type value) by getting the display-swapchain property.";
        public string SchemaLabel_Mpv_d3d11va_zero_copy { get; set; } = "Zero-copy decode output";
        public string SchemaDesc_Mpv_d3d11va_zero_copy { get; set; } = "By default, when using hardware decoding with --gpu-api=d3d11, the video image will be copied (GPU-to-GPU) from the decoder surface to a shader resource. Set this option to avoid that copy by sampling directly from the decoder image. This may increase performance and reduce power usage, but can cause the image to be sampled incorrectly on the bottom and right edges due to padding, and may invoke driver bugs, since Direct3D 11 technically does not allow sampling from a decoder surface (though most drivers support it.)";
        public string SchemaLabel_Mpv_deinterlace_field_parity { get; set; } = "Deinterlace field order";
        public string SchemaDesc_Mpv_deinterlace_field_parity { get; set; } = "Specify the field parity/order when deinterlacing (default: auto). Each frame of an interlaced video is divided into two fields, which are then separately transmitted. Top field represents even lines while bottom field represents odd lines. When deinterlacing the deinterlacer needs to know the correct temporal order of the fields else the video will appear jittery.";
        public string SchemaLabel_Mpv_demuxer { get; set; } = "Force demuxer";
        public string SchemaDesc_Mpv_demuxer { get; set; } = "Force demuxer type. Use a '+' before the name to force it; this will skip some checks. Give the demuxer name as printed by --demuxer=help.";
        public string SchemaLabel_Mpv_demuxer_backward_playback_step { get; set; } = "Backward playback step";
        public string SchemaDesc_Mpv_demuxer_backward_playback_step { get; set; } = "Number of seconds the demuxer should seek back to get new packets during backward playback (default: 60). This is useful for tuning backward playback, see --play-direction for details.";
        public string SchemaLabel_Mpv_demuxer_cache_unlink_files { get; set; } = "Delete cache files";
        public string SchemaDesc_Mpv_demuxer_cache_unlink_files { get; set; } = "Whether or when to unlink cache files (default: immediate). This affects cache files which are inherently temporary, and which make no sense to remain on disk after the player terminates. This is a debugging option.";
        public string SchemaLabel_Mpv_demuxer_cache_wait { get; set; } = "Cache before playback";
        public string SchemaDesc_Mpv_demuxer_cache_wait { get; set; } = "Before starting playback, read data until either the end of the file was reached, or the demuxer cache has reached maximum capacity. Only once this is done, playback starts. This intentionally happens before the initial seek triggered with --start. This does not change any runtime behavior after the initial caching. This option is useless if the file cannot be cached completely.";
        public string SchemaLabel_Mpv_demuxer_donate_buffer { get; set; } = "Share forward buffer";
        public string SchemaDesc_Mpv_demuxer_donate_buffer { get; set; } = "Whether to let the back buffer use part of the forward buffer (default: yes). If set to yes, the \"donation\" behavior described in the option description for --demuxer-max-back-bytes is enabled. This means the back buffer may use up memory up to the sum of the forward and back buffer options, minus the active size of the forward buffer. If set to no, the options strictly limit the forward and back buffer sizes separately.";
        public string SchemaLabel_Mpv_demuxer_hysteresis_bytes { get; set; } = "Buffer refill threshold";
        public string SchemaDesc_Mpv_demuxer_hysteresis_bytes { get; set; } = "Same as --demuxer-hysteresis-secs, but specifies the hysteresis in bytes of forward buffered data instead of seconds. Once the demuxer limit is reached, the demuxer will not buffer ahead again until the amount of forward buffered data drops to this value.";
        public string SchemaLabel_Mpv_demuxer_lavf_allow_mimetype { get; set; } = "Trust HTTP MIME type";
        public string SchemaDesc_Mpv_demuxer_lavf_allow_mimetype { get; set; } = "Allow deriving the format from the HTTP MIME type (default: yes). Set this to no in case playing things from HTTP mysteriously fails, even though the same files work from local disk.";
        public string SchemaLabel_Mpv_demuxer_lavf_analyzeduration { get; set; } = "Analysis duration";
        public string SchemaDesc_Mpv_demuxer_lavf_analyzeduration { get; set; } = "Maximum length in seconds to analyze the stream properties.";
        public string SchemaLabel_Mpv_demuxer_lavf_buffersize { get; set; } = "Read buffer size";
        public string SchemaDesc_Mpv_demuxer_lavf_buffersize { get; set; } = "Size of the stream read buffer allocated for libavformat in bytes (default: 32768). Lowering the size could lower latency. Note that libavformat might reallocate the buffer internally, or not fully use all of it.";
        public string SchemaLabel_Mpv_demuxer_lavf_format { get; set; } = "Force libavformat demuxer";
        public string SchemaDesc_Mpv_demuxer_lavf_format { get; set; } = "Force a specific libavformat demuxer.";
        public string SchemaLabel_Mpv_demuxer_lavf_hacks { get; set; } = "Format workarounds";
        public string SchemaDesc_Mpv_demuxer_lavf_hacks { get; set; } = "By default, some formats will be handled differently from other formats by explicitly checking for them. Most of these compensate for weird or imperfect behavior from libavformat demuxers. Passing no disables these. For debugging and testing only.";
        public string SchemaLabel_Mpv_demuxer_lavf_linearize_timestamps { get; set; } = "Smooth timestamp resets";
        public string SchemaDesc_Mpv_demuxer_lavf_linearize_timestamps { get; set; } = "Attempt to linearize timestamp resets in demuxed streams (default: auto). This was tested only for single audio streams. It's unknown whether it works correctly for video (but likely won't). Note that the implementation is slightly incorrect either way, and will introduce a discontinuity by about 1 codec frame size.";
        public string SchemaLabel_Mpv_demuxer_lavf_probe_info { get; set; } = "Probe stream info";
        public string SchemaDesc_Mpv_demuxer_lavf_probe_info { get; set; } = "Whether to probe stream information (default: auto). Technically, this controls whether libavformat's avformat_find_stream_info() function is called. Usually it's safer to call it, but it can also make startup slower.";
        public string SchemaLabel_Mpv_demuxer_lavf_probescore { get; set; } = "Format detection threshold";
        public string SchemaDesc_Mpv_demuxer_lavf_probescore { get; set; } = "Minimum required libavformat probe score. Lower values will require less data to be loaded (makes streams start faster), but makes file format detection less reliable. Can be used to force auto-detected libavformat demuxers, even if libavformat considers the detection not reliable enough. (Default: 26.)";
        public string SchemaLabel_Mpv_demuxer_lavf_probesize { get; set; } = "Probe size limit";
        public string SchemaDesc_Mpv_demuxer_lavf_probesize { get; set; } = "Maximum amount of data to probe during the detection phase. In the case of MPEG-TS this value identifies the maximum number of TS packets to scan.";
        public string SchemaLabel_Mpv_demuxer_lavf_propagate_opts { get; set; } = "Pass options down";
        public string SchemaDesc_Mpv_demuxer_lavf_propagate_opts { get; set; } = "Propagate FFmpeg-level options to recursively opened connections (default: yes). This is needed because FFmpeg will apply these settings to nested AVIO contexts automatically. On the other hand, this could break in certain situations - it's the FFmpeg API, you just can't win.";
        public string SchemaLabel_Mpv_demuxer_mkv_crop_compat { get; set; } = "Matroska crop compat";
        public string SchemaDesc_Mpv_demuxer_mkv_crop_compat { get; set; } = "Enable compatibility mode for files that do not fully comply with the Matroska specification. (default: yes)";
        public string SchemaLabel_Mpv_demuxer_mkv_probe_start_time { get; set; } = "Read Matroska start time";
        public string SchemaDesc_Mpv_demuxer_mkv_probe_start_time { get; set; } = "Check the start time of Matroska files (default: yes). This simply reads the first cluster timestamps and assumes it is the start time. Technically, this also reads the first timestamp, which may increase latency by one frame (which may be relevant for live streams).";
        public string SchemaLabel_Mpv_demuxer_mkv_probe_video_duration { get; set; } = "Probe duration from tail";
        public string SchemaDesc_Mpv_demuxer_mkv_probe_video_duration { get; set; } = "When opening the file, seek to the end of it, and check what timestamp the last video packet has, and report that as file duration. This is strictly for compatibility with Haali only. In this mode, it's possible that opening will be slower (especially when playing over http), or that behavior with broken files is much worse. So don't use this option.";
        public string SchemaLabel_Mpv_demuxer_mkv_subtitle_preroll { get; set; } = "Subtitle preroll on seek";
        public string SchemaDesc_Mpv_demuxer_mkv_subtitle_preroll { get; set; } = "Try harder to show embedded soft subtitles when seeking somewhere. Normally, it can happen that the subtitle at the seek target is not shown due to how some container file formats are designed. The subtitles appear only if seeking before or exactly to the position a subtitle first appears. To make this worse, subtitles are often timed to appear a very small amount before the associated video frame, so that seeking to the video frame typically does not demux the subtitle at that position.";
        public string SchemaLabel_Mpv_demuxer_mkv_subtitle_preroll_secs { get; set; } = "Preroll window";
        public string SchemaDesc_Mpv_demuxer_mkv_subtitle_preroll_secs { get; set; } = "See --demuxer-mkv-subtitle-preroll.";
        public string SchemaLabel_Mpv_demuxer_mkv_subtitle_preroll_secs_index { get; set; } = "Preroll window with index";
        public string SchemaDesc_Mpv_demuxer_mkv_subtitle_preroll_secs_index { get; set; } = "See --demuxer-mkv-subtitle-preroll.";
        public string SchemaLabel_Mpv_demuxer_rawaudio_channels { get; set; } = "Raw audio channels";
        public string SchemaDesc_Mpv_demuxer_rawaudio_channels { get; set; } = "Number of channels (or channel layout) if --demuxer=rawaudio is used (default: stereo).";
        public string SchemaLabel_Mpv_demuxer_rawaudio_format { get; set; } = "Raw audio sample format";
        public string SchemaDesc_Mpv_demuxer_rawaudio_format { get; set; } = "Sample format for --demuxer=rawaudio (default: s16le). Use --demuxer-rawaudio-format=help to get a list of all formats.";
        public string SchemaLabel_Mpv_demuxer_rawaudio_rate { get; set; } = "Raw audio sample rate";
        public string SchemaDesc_Mpv_demuxer_rawaudio_rate { get; set; } = "Sample rate for --demuxer=rawaudio (default: 44 kHz).";
        public string SchemaLabel_Mpv_demuxer_rawvideo_codec { get; set; } = "Raw video codec";
        public string SchemaDesc_Mpv_demuxer_rawvideo_codec { get; set; } = "Set the video codec instead of selecting the rawvideo codec when using --demuxer=rawvideo. This uses the same values as codec names in --vd (but it does not accept decoder names).";
        public string SchemaLabel_Mpv_demuxer_rawvideo_format { get; set; } = "Raw video pixel format";
        public string SchemaDesc_Mpv_demuxer_rawvideo_format { get; set; } = "Color space (fourcc) in hex or string for --demuxer=rawvideo (default: YV12).";
        public string SchemaLabel_Mpv_demuxer_rawvideo_fps { get; set; } = "Raw video frame rate";
        public string SchemaDesc_Mpv_demuxer_rawvideo_fps { get; set; } = "Rate in frames per second for --demuxer=rawvideo (default: 25.0).";
        public string SchemaLabel_Mpv_demuxer_rawvideo_h { get; set; } = "Raw video height";
        public string SchemaDesc_Mpv_demuxer_rawvideo_h { get; set; } = "Image dimension in pixels for --demuxer=rawvideo.";
        public string SchemaLabel_Mpv_demuxer_rawvideo_mp_format { get; set; } = "Raw video internal format";
        public string SchemaDesc_Mpv_demuxer_rawvideo_mp_format { get; set; } = "Color space by internal video format for --demuxer=rawvideo. Use --demuxer-rawvideo-mp-format=help for a list of possible formats.";
        public string SchemaLabel_Mpv_demuxer_rawvideo_size { get; set; } = "Raw video frame size";
        public string SchemaDesc_Mpv_demuxer_rawvideo_size { get; set; } = "Frame size in bytes when using --demuxer=rawvideo.";
        public string SchemaLabel_Mpv_demuxer_rawvideo_w { get; set; } = "Raw video width";
        public string SchemaDesc_Mpv_demuxer_rawvideo_w { get; set; } = "Image dimension in pixels for --demuxer=rawvideo.";
        public string SchemaLabel_Mpv_demuxer_seekable_cache { get; set; } = "Seek using cache";
        public string SchemaDesc_Mpv_demuxer_seekable_cache { get; set; } = "Debugging option to control whether seeking can use the demuxer cache (default: auto). Normally you don't ever need to set this; the default auto does the right thing and enables cache seeking it if --cache is set to yes (or is implied yes if --cache=auto).";
        public string SchemaLabel_Mpv_demuxer_termination_timeout { get; set; } = "Shutdown wait";
        public string SchemaDesc_Mpv_demuxer_termination_timeout { get; set; } = "Number of seconds the player should wait to shutdown the demuxer (default: 0.1). The player will wait up to this much time before it closes the stream layer forcefully. Forceful closing usually means the network I/O is given no chance to close its connections gracefully (of course the OS can still close TCP connections properly), and might result in annoying messages being logged, and in some cases, confused remote servers.";
        public string SchemaLabel_Mpv_demuxer_thread { get; set; } = "Background demuxing";
        public string SchemaDesc_Mpv_demuxer_thread { get; set; } = "Run the demuxer in a separate thread, and let it prefetch a certain amount of packets (default: yes). Having this enabled leads to smoother playback, enables features like prefetching, and prevents that stuck network freezes the player. On the other hand, it can add overhead, or the background prefetching can hog CPU resources.";
        public string SchemaLabel_Mpv_display_fps_override { get; set; } = "Display refresh rate";
        public string SchemaDesc_Mpv_display_fps_override { get; set; } = "Set the display FPS used with the --video-sync=display-* modes. By default, a detected value is used. Keep in mind that setting an incorrect value (even if slightly incorrect) can ruin video playback. On multi-monitor systems, there is a chance that the detected value is from the wrong monitor.";
        public string SchemaLabel_Mpv_display_tags { get; set; } = "Shown metadata tags";
        public string SchemaDesc_Mpv_display_tags { get; set; } = "Set the list of tags that should be displayed on the terminal and stats. Tags that are in the list, but are not present in the played file, will not be shown. If a value ends with *, all tags are matched by prefix (though there is no general globbing). Just passing * essentially filtering.";
        public string SchemaLabel_Mpv_drag_and_drop { get; set; } = "Drag and drop action";
        public string SchemaDesc_Mpv_drag_and_drop { get; set; } = "Controls the default built-in drag-and-drop behavior (--input-builtin-drag-and-drop). auto will obey the action value in dropped-files property. replace, append, and insert-next always force replacing, appending to, and inserting next into the playlist respectively. no disables all drag and drop behavior.";
        public string SchemaLabel_Mpv_dvd_angle { get; set; } = "DVD angle";
        public string SchemaDesc_Mpv_dvd_angle { get; set; } = "Some DVDs contain scenes that can be viewed from multiple angles. This option tells mpv which angle to use (default: 1).";
        public string SchemaLabel_Mpv_dvd_device { get; set; } = "DVD device or image";
        public string SchemaDesc_Mpv_dvd_device { get; set; } = "Specify the DVD device or .iso filename. You can also specify a directory that contains files previously copied directly from a DVD (with e.g. vobcopy). The default device path depends on the OS. See the OPTICAL DRIVES section.";
        public string SchemaLabel_Mpv_dvd_speed { get; set; } = "DVD read speed";
        public string SchemaDesc_Mpv_dvd_speed { get; set; } = "Try to limit DVD speed (default: 0, no change). DVD base speed is 1385 kB/s, so an 8x drive can read at speeds up to 11080 kB/s. Slower speeds make the drive more quiet. For watching DVDs, 2700 kB/s should be quiet and fast enough. mpv resets the speed to the drive default value on close. Values of at least 100 mean speed in kB/s. Values less than 100 mean multiples of 1385 kB/s, i.e. --dvd-speed=8 selects 11080 kB/s.";
        public string SchemaLabel_Mpv_edition { get; set; } = "Matroska edition";
        public string SchemaDesc_Mpv_edition { get; set; } = "(Matroska files only) Specify the edition (set of chapters) to use, where 0 is the first. If set to auto (the default), mpv will choose the first edition declared as a default, or if there is no default, the first edition defined.";
        public string SchemaLabel_Mpv_end { get; set; } = "Stop at time";
        public string SchemaDesc_Mpv_end { get; set; } = "Stop at given time. Use --length if the time should be relative to --start. See --start for valid option values and examples.";
        public string SchemaLabel_Mpv_error_diffusion { get; set; } = "Error diffusion kernel";
        public string SchemaDesc_Mpv_error_diffusion { get; set; } = "The error diffusion kernel to use when --dither=error-diffusion is set.";
        public string SchemaLabel_Mpv_external_files { get; set; } = "Add all tracks from file";
        public string SchemaDesc_Mpv_external_files { get; set; } = "Load a file and add all of its tracks. This is useful to play different files together (for example audio from one file, video from another), or for advanced --lavfi-complex used (like playing two video files at the same time).";
        public string SchemaLabel_Mpv_fbo_format { get; set; } = "Render target format";
        public string SchemaDesc_Mpv_fbo_format { get; set; } = "Selects the internal format of textures used for FBOs. The format can influence performance and quality of the video output. fmt can be one of: rgb8, rgb10, rgb10_a2, rgb16, rgb16f, rgb32f, rgba12, rgba16, rgba16f, rgba16hf, rgba32f.";
        public string SchemaLabel_Mpv_flatten_editions { get; set; } = "Flatten editions";
        public string SchemaDesc_Mpv_flatten_editions { get; set; } = "Some container formats (such as HLS or MPEG-TS with multiple programs) expose multiple programs or rendition groups. By default, mpv respects the format and groups tracks into editions, filtering the track list to only show tracks belonging to the currently selected edition.";
        public string SchemaLabel_Mpv_force_media_title { get; set; } = "Force media title";
        public string SchemaDesc_Mpv_force_media_title { get; set; } = "Force the contents of the media-title property to this value. Useful for scripts which want to set a title, without overriding the user's setting in --title.";
        public string SchemaLabel_Mpv_force_render { get; set; } = "Always render frames";
        public string SchemaDesc_Mpv_force_render { get; set; } = "Forces mpv to always render frames regardless of the visibility of the window. Currently only affects X11, Wayland and macvk VOs since they are the only ones that have this optimization (i.e. everything else always renders regardless of visibility).";
        public string SchemaLabel_Mpv_force_rgba_osd_rendering { get; set; } = "Force RGBA OSD rendering";
        public string SchemaDesc_Mpv_force_rgba_osd_rendering { get; set; } = "Change how some video outputs render the OSD and text subtitles. This does not change appearance of the subtitles and only has performance implications. For VOs which support native ASS rendering (like gpu, vdpau, direct3d), this can be slightly faster or slower, depending on GPU drivers and hardware. For other VOs, this just makes rendering slower.";
        public string SchemaLabel_Mpv_force_seekable { get; set; } = "Force seeking";
        public string SchemaDesc_Mpv_force_seekable { get; set; } = "If the player thinks that the media is not seekable (e.g. playing from a pipe, or it's an http stream with a server that doesn't support range requests), seeking will be disabled. This option can forcibly enable it. For seeks within the cache, there's a good chance of success.";
        public string SchemaLabel_Mpv_force_window { get; set; } = "Always create a window";
        public string SchemaDesc_Mpv_force_window { get; set; } = "Create a video output window even if there is no video. This can be useful when pretending that mpv is a GUI application. Currently, the window always has the size 960x540, and is subject to --geometry, --autofit, and similar options.";
        public string SchemaLabel_Mpv_force_window_position { get; set; } = "Keep initial window position";
        public string SchemaDesc_Mpv_force_window_position { get; set; } = "Controls whether the window is moved back to its initial position after an automatic resize due to video stream size changes (see --auto-window-resize). When disabled, the window preserves its current position and only resizes to match the new video size. When enabled, the window is repositioned to the initial location set by --geometry, or the center of the screen if no geometry is specified. Currently only affects Windows, X11, macvk and SDL VOs. (default: no)";
        public string SchemaLabel_Mpv_framedrop { get; set; } = "Frame dropping";
        public string SchemaDesc_Mpv_framedrop { get; set; } = "Skip displaying some frames to maintain A/V sync on slow systems, or playing high framerate video on video outputs that have an upper framerate limit.";
        public string SchemaLabel_Mpv_frames { get; set; } = "Limit frames";
        public string SchemaDesc_Mpv_frames { get; set; } = "Play/convert only first <number> video frames, then quit.";
        public string SchemaLabel_Mpv_fs_screen { get; set; } = "Fullscreen monitor";
        public string SchemaDesc_Mpv_fs_screen { get; set; } = "In multi-monitor configurations (i.e. a single desktop that spans across multiple displays), this option tells mpv which screen to go fullscreen to. If current is used mpv will fallback on what the user provided with the screen option.";
        public string SchemaLabel_Mpv_fs_screen_name { get; set; } = "Fullscreen monitor by name";
        public string SchemaDesc_Mpv_fs_screen_name { get; set; } = "In multi-monitor configurations, this option tells mpv which screen to go fullscreen to based on the screen name from the video backend. The same caveats in the --fs-screen option also apply here. This option is ignored and does nothing if --fs-screen is explicitly set.";
        public string SchemaLabel_Mpv_gamma_factor { get; set; } = "Extra gamma factor";
        public string SchemaDesc_Mpv_gamma_factor { get; set; } = "Set an additional raw gamma factor (default: 1.0). If gamma is adjusted in other ways (like with the --gamma option or key bindings and the gamma property), the value is multiplied with the other gamma value.";
        public string SchemaLabel_Mpv_geometry { get; set; } = "Window position and size";
        public string SchemaDesc_Mpv_geometry { get; set; } = "Adjust the initial window position or size. W and H set the window size in pixels. x and y set the window position, measured in pixels from the top-left corner of the screen to the top-left corner of the image being displayed. If a percentage sign (%) is given after the argument, it turns the value into a percentage of the screen size in that direction. Positions are specified similar to the standard X11 --geometry option format, in which e.g. +10-50 means \"place 10 pixels from the left border and 50 pixels from the lower border\" and \"--20+-10\" means \"place 20 pixels beyond the right and 10 pixels beyond the top border\". A trailing / followed by an integer denotes on which workspace (virtual desktop) the window should appear (X11 only).";
        public string SchemaLabel_Mpv_gpu_hwdec_interop { get; set; } = "Hardware interop backend";
        public string SchemaDesc_Mpv_gpu_hwdec_interop { get; set; } = "This option is for troubleshooting hwdec interop issues. Since it's a debugging option, its semantics may change at any time.";
        public string SchemaLabel_Mpv_gpu_tex_pad_x { get; set; } = "Texture padding, horizontal";
        public string SchemaDesc_Mpv_gpu_tex_pad_x { get; set; } = "Enlarge the video source textures by this many pixels. For debugging only (normally textures are sized exactly, but due to hardware decoding interop we may have to deal with additional padding, which can be tested with these options). Could be removed any time.";
        public string SchemaLabel_Mpv_gpu_tex_pad_y { get; set; } = "Texture padding, vertical";
        public string SchemaDesc_Mpv_gpu_tex_pad_y { get; set; } = "Enlarge the video source textures by this many pixels. For debugging only (normally textures are sized exactly, but due to hardware decoding interop we may have to deal with additional padding, which can be tested with these options). Could be removed any time.";
        public string SchemaLabel_Mpv_hdr_peak_percentile { get; set; } = "HDR peak sample";
        public string SchemaDesc_Mpv_hdr_peak_percentile { get; set; } = "Which percentile of the input image brightness histogram to consider as the true peak of the scene. If this is set to 100 (default), the brightest pixel is measured. Otherwise, the top of the frequency distribution is progressively cut off. Setting this too low will cause clipping of very bright details, but can improve the dynamic brightness range of scenes with very bright isolated highlights. Values other than 100 come with a small performance penalty. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_hdr_reference_white { get; set; } = "HDR reference white";
        public string SchemaDesc_Mpv_hdr_reference_white { get; set; } = "Specifies the assumed peak brightness of the mastering display for SDR content, in cd/m² (nits). This is used as HDR diffuse white level for SDR content. Essentially this is the SDR brightness in HDR container. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_hidpi_window_scale { get; set; } = "Scale window by DPI";
        public string SchemaDesc_Mpv_hidpi_window_scale { get; set; } = "Scale the window size according to the backing DPI scale factor from the OS (default: no). For example, if the OS DPI scaling is set to 200%, mpv's window size will be multiplied by 2.";
        public string SchemaLabel_Mpv_hls_bitrate { get; set; } = "HLS bitrate selection";
        public string SchemaDesc_Mpv_hls_bitrate { get; set; } = "If HLS streams are played, this option controls what streams are selected by default. The option allows the following parameters:";
        public string SchemaLabel_Mpv_hr_seek_demuxer_offset { get; set; } = "Precise seek margin";
        public string SchemaDesc_Mpv_hr_seek_demuxer_offset { get; set; } = "This option exists to work around failures to do precise seeks (as in --hr-seek) caused by bugs or limitations in the demuxers for some file formats. Some demuxers fail to seek to a keyframe before the given target position, going to a later position instead. The value of this option is subtracted from the time stamp given to the demuxer. Thus, if you set this option to 1.5 and try to do a precise seek to 60 seconds, the demuxer is told to seek to time 58.5, which hopefully reduces the chance that it erroneously goes to some time later than 60 seconds. The downside of setting this option is that precise seeks become slower, as video between the earlier demuxer position and the real target may be unnecessarily decoded.";
        public string SchemaLabel_Mpv_hwdec_extra_frames { get; set; } = "Extra hardware frames";
        public string SchemaDesc_Mpv_hwdec_extra_frames { get; set; } = "Number of extra GPU frames hardware decoding should preallocate, on top of what the codec itself requires (default: auto).";
        public string SchemaLabel_Mpv_hwdec_image_format { get; set; } = "Hardware pixel format";
        public string SchemaDesc_Mpv_hwdec_image_format { get; set; } = "Set the internal pixel format used by hardware decoding via --hwdec (default no). The special value no selects an implementation specific standard format. Most decoder implementations support only one format, and will fail to initialize if the format is not supported.";
        public string SchemaLabel_Mpv_hwdec_software_fallback { get; set; } = "Fallback to software decoding";
        public string SchemaDesc_Mpv_hwdec_software_fallback { get; set; } = "Fallback to software decoding if the hardware-accelerated decoder fails (default: 3). If this is a number, then fallback will be triggered if N frames fail to decode in a row. 1 is equivalent to yes.";
        public string SchemaLabel_Mpv_hwdec_threads { get; set; } = "Hardware decode threads";
        public string SchemaDesc_Mpv_hwdec_threads { get; set; } = "Number of threads used for hardware decoding (default: 4). This, as opposed to vd-queue, enables frame and slice threading in libavcodec. It can help with pipelining the decoding process and improve performance. The exact behavior depends on the hardware decoder API used.";
        public string SchemaLabel_Mpv_icc_intent { get; set; } = "ICC rendering intent";
        public string SchemaDesc_Mpv_icc_intent { get; set; } = "Specifies the ICC intent used for the color transformation (when using --icc-profile).";
        public string SchemaLabel_Mpv_icc_use_luma { get; set; } = "Use ICC luminance";
        public string SchemaDesc_Mpv_icc_use_luma { get; set; } = "Use ICC profile luminance value. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_idle { get; set; } = "Stay open with no file";
        public string SchemaDesc_Mpv_idle { get; set; } = "Makes mpv wait idly instead of quitting when there is no file to play. Mostly useful in input mode, where mpv can be controlled through input commands. (Default: no)";
        public string SchemaLabel_Mpv_ignore_path_in_watch_later_config { get; set; } = "Ignore path in resume data";
        public string SchemaDesc_Mpv_ignore_path_in_watch_later_config { get; set; } = "Ignore path (i.e. use filename only) when using watch later feature. (Default: disabled)";
        public string SchemaLabel_Mpv_image_lut { get; set; } = "Decode-time LUT file";
        public string SchemaDesc_Mpv_image_lut { get; set; } = "Specifies a custom LUT file (in Adobe .cube format) to apply to the colors during image decoding. The exact interpretation of the LUT depends on the value of --image-lut-type. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_image_lut_type { get; set; } = "Decode-time LUT type";
        public string SchemaDesc_Mpv_image_lut_type { get; set; } = "Controls the interpretation of color values fed to and from the LUT specified as --image-lut. Valid values are:";
        public string SchemaLabel_Mpv_include { get; set; } = "Extra config file";
        public string SchemaDesc_Mpv_include { get; set; } = "Specify configuration file to be parsed after the default ones.";
        public string SchemaLabel_Mpv_index { get; set; } = "Seek index";
        public string SchemaDesc_Mpv_index { get; set; } = "Controls how to seek in files. Note that if the index is missing from a file, it will be built on the fly by default, so you don't need to change this. But it might help with some broken files.";
        public string SchemaLabel_Mpv_initial_audio_sync { get; set; } = "Align audio at start";
        public string SchemaDesc_Mpv_initial_audio_sync { get; set; } = "When starting a video file or after events such as seeking, mpv will by default modify the audio stream to make it start from the same timestamp as video, by either inserting silence at the start or cutting away the first samples. Disabling this option makes the player behave like older mpv versions did: video and audio are both started immediately even if their start timestamps differ, and then video timing is gradually adjusted if necessary to reach correct synchronization later.";
        public string SchemaLabel_Mpv_input_ar_delay { get; set; } = "Key repeat delay";
        public string SchemaDesc_Mpv_input_ar_delay { get; set; } = "Delay in milliseconds before we start to autorepeat a key (default: 200). Set it to 0 to disable.";
        public string SchemaLabel_Mpv_input_ar_rate { get; set; } = "Key repeat rate";
        public string SchemaDesc_Mpv_input_ar_rate { get; set; } = "Number of key presses to generate per second on autorepeat (default: 40).";
        public string SchemaLabel_Mpv_input_builtin_bindings { get; set; } = "Built-in key bindings";
        public string SchemaDesc_Mpv_input_builtin_bindings { get; set; } = "Enable loading of built-in key bindings during start-up (default: yes). This option is applied only during (lib)mpv initialization, and if disabled then it will not be not possible to enable them later. May be useful to libmpv clients.";
        public string SchemaLabel_Mpv_input_builtin_drag_and_drop { get; set; } = "Drag and drop files";
        public string SchemaDesc_Mpv_input_builtin_drag_and_drop { get; set; } = "Enable the built-in drag-and-drop behavior (default: yes). Setting it to no disables the built-in drag-and-drop handling.";
        public string SchemaLabel_Mpv_input_builtin_dragging { get; set; } = "Drag window by content";
        public string SchemaDesc_Mpv_input_builtin_dragging { get; set; } = "Enable the built-in window-dragging behavior (default: yes). Setting it to no disables the built-in dragging behavior. Note that unlike the window-dragging option, this option only affects VOs which support the begin-vo-dragging command, and does not disable window dragging initialized with the command.";
        public string SchemaLabel_Mpv_input_commands { get; set; } = "Startup commands";
        public string SchemaDesc_Mpv_input_commands { get; set; } = "Define a list of commands for mpv to run. The syntax is the same as format as input.conf but without the key binding argument at the beginning. When this option is set at startup, the commands will run after audio and video playback are about to begin if applicable (in idle mode with no file, it will run immediately). When changing values at runtime, the commands will also run as soon as possible.";
        public string SchemaLabel_Mpv_input_conf { get; set; } = "Key binding file";
        public string SchemaDesc_Mpv_input_conf { get; set; } = "Specify input configuration file other than the default location in the mpv configuration directory (usually ~/.config/mpv/input.conf).";
        public string SchemaLabel_Mpv_input_cursor { get; set; } = "Receive pointer events";
        public string SchemaDesc_Mpv_input_cursor { get; set; } = "Permit mpv to receive pointer events reported by the video output driver. Necessary to use the OSC. Support depends on the VO in use.";
        public string SchemaLabel_Mpv_input_cursor_passthrough { get; set; } = "Pass clicks through";
        public string SchemaDesc_Mpv_input_cursor_passthrough { get; set; } = "Tell the backend windowing system to allow pointer events to passthrough the mpv window. This allows windows under mpv to instead receive pointer events as if the mpv window was never there.";
        public string SchemaLabel_Mpv_input_default_bindings { get; set; } = "Overridable key bindings";
        public string SchemaDesc_Mpv_input_default_bindings { get; set; } = "Enable default-level (\"weak\") key bindings (default: yes). These are bindings which config files like input.conf can override. It currently affects the builtin key bindings, and keys which scripts bind using mp.add_key_binding (but not mp.add_forced_key_binding because this overrides input.conf).";
        public string SchemaLabel_Mpv_input_doubleclick_time { get; set; } = "Double click interval";
        public string SchemaDesc_Mpv_input_doubleclick_time { get; set; } = "Time in milliseconds to recognize two consecutive button presses as a double-click (default: 300).";
        public string SchemaLabel_Mpv_input_dragging_deadzone { get; set; } = "Drag start threshold";
        public string SchemaDesc_Mpv_input_dragging_deadzone { get; set; } = "Begin the built-in window dragging when the mouse moves outside a deadzone of N pixels while the mouse button is being held down (default: 3). This only affects VOs which support the begin-vo-dragging command.";
        public string SchemaLabel_Mpv_input_key_fifo_size { get; set; } = "Key event buffer";
        public string SchemaDesc_Mpv_input_key_fifo_size { get; set; } = "Specify the size of the FIFO that buffers key events (default: 7). If it is too small, some events may be lost. The main disadvantage of setting it to a very large value is that if you hold down a key triggering some particularly slow command then the player may be unresponsive while it processes all the queued commands.";
        public string SchemaLabel_Mpv_input_media_keys { get; set; } = "Capture media keys";
        public string SchemaDesc_Mpv_input_media_keys { get; set; } = "On systems where mpv can choose between receiving media keys or letting the system handle them - this option controls whether mpv should receive them.";
        public string SchemaLabel_Mpv_input_preprocess_wheel { get; set; } = "Filter wheel events";
        public string SchemaDesc_Mpv_input_preprocess_wheel { get; set; } = "Preprocess WHEEL_* events so that while scrolling on the horizontal or vertical direction, the events aren't generated for another direction even when the two directions are scrolled together (default: yes).";
        public string SchemaLabel_Mpv_input_right_alt_gr { get; set; } = "Right Alt as Alt Gr";
        public string SchemaDesc_Mpv_input_right_alt_gr { get; set; } = "(macOS and Windows only) Use the right Alt key as Alt Gr to produce special characters. If disabled, count the right Alt as an Alt modifier key. Enabled by default.";
        public string SchemaLabel_Mpv_input_tablet_emulate_mouse { get; set; } = "Tablet as mouse";
        public string SchemaDesc_Mpv_input_tablet_emulate_mouse { get; set; } = "Emulate mouse move and button presses for tablet events (default: yes).";
        public string SchemaLabel_Mpv_input_touch_emulate_mouse { get; set; } = "Touch as mouse";
        public string SchemaDesc_Mpv_input_touch_emulate_mouse { get; set; } = "When multi-touch support is enabled (either required by the platform, or enabled by --native-touch), emulate mouse move and button presses for the touch events (default: yes). This is useful for compatibility for mouse key bindings and scripts which read mouse positions for platforms which do not support --native-touch=no (e.g. Wayland).";
        public string SchemaLabel_Mpv_input_vo_keyboard { get; set; } = "Keyboard input";
        public string SchemaDesc_Mpv_input_vo_keyboard { get; set; } = "Disable all keyboard input on for VOs which can't participate in proper keyboard input dispatching. May not affect all VOs. Generally useful for embedding only.";
        public string SchemaLabel_Mpv_interpolation_preserve { get; set; } = "Preserve interpolation cache";
        public string SchemaDesc_Mpv_interpolation_preserve { get; set; } = "Preserve the previous frames' interpolated results even when renderer parameters are changed - with the exception of options related to cropping and video placement, which always invalidate the cache. Enabling this option makes dynamic updates of renderer settings slightly smoother at the cost of slightly higher latency in response to such changes. Defaults to on. (Only affects --vo=gpu-next, note that --vo=gpu always invalidates interpolated frames)";
        public string SchemaLabel_Mpv_interpolation_threshold { get; set; } = "Interpolation threshold";
        public string SchemaDesc_Mpv_interpolation_threshold { get; set; } = "Threshold below which frame ratio interpolation gets disabled (default: 0.01). This is calculated as abs(disphz/vfps - 1) < threshold, where vfps is the speed-adjusted video FPS, and disphz the display refresh rate. (The speed-adjusted video FPS is roughly equal to the normal video FPS, but with slowdown and speedup applied. This matters if you use --video-sync=display-resample to make video run synchronously to the display FPS, or if you change the speed property.)";
        public string SchemaLabel_Mpv_keep_open_pause { get; set; } = "Pause at end of file";
        public string SchemaDesc_Mpv_keep_open_pause { get; set; } = "If set to no, instead of pausing when --keep-open is active, just stop at end of file and continue playing forward when you seek backwards until end where it stops again. Default: yes.";
        public string SchemaLabel_Mpv_keepaspect { get; set; } = "Keep aspect ratio";
        public string SchemaDesc_Mpv_keepaspect { get; set; } = "--keepaspect=no will always stretch the video to window size, and will disable the window manager hints that force the window aspect ratio. (Ignored in fullscreen mode.)";
        public string SchemaLabel_Mpv_keepaspect_window { get; set; } = "Lock window to aspect";
        public string SchemaDesc_Mpv_keepaspect_window { get; set; } = "--keepaspect-window=yes (the default) will lock the window size to the video aspect. --keepaspect-window=no disables this behavior, and will instead add black bars if window aspect and video aspect mismatch. Whether this actually works depends on the VO backend. (Ignored in fullscreen mode.)";
        public string SchemaLabel_Mpv_lavfi_complex { get; set; } = "Multi-source filter graph";
        public string SchemaDesc_Mpv_lavfi_complex { get; set; } = "Set a \"complex\" libavfilter filter, which means a single filter graph can take input from multiple source audio and video tracks. The graph can result in a single audio or video output (or both).";
        public string SchemaLabel_Mpv_length { get; set; } = "Stop after duration";
        public string SchemaDesc_Mpv_length { get; set; } = "Stop after a given time relative to the start time. See --start for valid option values and examples.";
        public string SchemaLabel_Mpv_libplacebo_opts { get; set; } = "libplacebo raw options";
        public string SchemaDesc_Mpv_libplacebo_opts { get; set; } = "Passes extra raw option to the libplacebo rendering backend (used by --vo=gpu-next). May override the effects of any other options set using the normal options system. Requires libplacebo v6.309 or higher. Included for debugging purposes only. For more information, see:";
        public string SchemaLabel_Mpv_load_auto_profiles { get; set; } = "Conditional profiles";
        public string SchemaDesc_Mpv_load_auto_profiles { get; set; } = "Enable the builtin script that does auto profiles (default: auto). See Conditional auto profiles for details. auto will load the script, but immediately unload it if there are no conditional profiles.";
        public string SchemaLabel_Mpv_load_commands { get; set; } = "Command console";
        public string SchemaDesc_Mpv_load_commands { get; set; } = "Enable the built-in script to enter commands in the console (default: yes). The ` key is used to activate this by default.";
        public string SchemaLabel_Mpv_load_console { get; set; } = "Console script";
        public string SchemaDesc_Mpv_load_console { get; set; } = "Enable the built-in script to handle textual input (default: yes).";
        public string SchemaLabel_Mpv_load_context_menu { get; set; } = "Context menu script";
        public string SchemaDesc_Mpv_load_context_menu { get; set; } = "Enable the builtin script that implements a context menu. Defaults to yes on platforms where integration with a native context menu is not implemented, and to no on platform where it is.";
        public string SchemaLabel_Mpv_load_positioning { get; set; } = "Pan and zoom keys";
        public string SchemaDesc_Mpv_load_positioning { get; set; } = "Enable the builtin script that provides various keybindings to pan videos and images (default: yes).";
        public string SchemaLabel_Mpv_load_scripts { get; set; } = "Auto-load scripts";
        public string SchemaDesc_Mpv_load_scripts { get; set; } = "If set to no, don't auto-load scripts from the scripts configuration subdirectory (usually ~/.config/mpv/scripts/). (Default: yes)";
        public string SchemaLabel_Mpv_load_select { get; set; } = "List selection script";
        public string SchemaDesc_Mpv_load_select { get; set; } = "Enable the builtin script that lets you select from lists of items (default: yes). By default, its keybindings start with the g key.";
        public string SchemaLabel_Mpv_load_stats_overlay { get; set; } = "Statistics overlay";
        public string SchemaDesc_Mpv_load_stats_overlay { get; set; } = "Enable the builtin script that shows useful playback information on a key binding (default: yes). By default, the i key is used (I to make the overlay permanent).";
        public string SchemaLabel_Mpv_load_unsafe_playlists { get; set; } = "Allow unsafe playlists";
        public string SchemaDesc_Mpv_load_unsafe_playlists { get; set; } = "Load URLs from playlists which are considered unsafe (default: no). This includes special protocols and anything that doesn't refer to normal files. Local files and HTTP links on the other hand are always considered safe.";
        public string SchemaLabel_Mpv_lut { get; set; } = "LUT file";
        public string SchemaDesc_Mpv_lut { get; set; } = "Specifies a custom LUT (in Adobe .cube format) to apply to the colors as part of color conversion. The exact interpretation depends on the value of --lut-type. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_lut_type { get; set; } = "LUT type";
        public string SchemaDesc_Mpv_lut_type { get; set; } = "Controls the interpretation of color values fed to and from the LUT specified as --lut. Valid values are:";
        public string SchemaLabel_Mpv_media_controls { get; set; } = "System media controls";
        public string SchemaDesc_Mpv_media_controls { get; set; } = "(Windows only) Enable integration of media control interface SystemMediaTransportControls.";
        public string SchemaLabel_Mpv_merge_files { get; set; } = "Treat files as one";
        public string SchemaDesc_Mpv_merge_files { get; set; } = "Pretend that all files passed to mpv are concatenated into a single, big file. This uses timeline/EDL support internally.";
        public string SchemaLabel_Mpv_mf_fps { get; set; } = "Image sequence frame rate";
        public string SchemaDesc_Mpv_mf_fps { get; set; } = "Framerate used when decoding from multiple PNG or JPEG files with mf:// (default: 1).";
        public string SchemaLabel_Mpv_mf_type { get; set; } = "Image sequence type";
        public string SchemaDesc_Mpv_mf_type { get; set; } = "Input file type for mf:// (available: jpeg, png, tga, sgi). By default, this is guessed from the file extension.";
        public string SchemaLabel_Mpv_monitoraspect { get; set; } = "Monitor aspect ratio";
        public string SchemaDesc_Mpv_monitoraspect { get; set; } = "Set the aspect ratio of your monitor or TV screen. A value of 0 disables a previous setting (e.g. in the config file). Overrides the --monitorpixelaspect setting if enabled.";
        public string SchemaLabel_Mpv_monitorpixelaspect { get; set; } = "Monitor pixel aspect";
        public string SchemaDesc_Mpv_monitorpixelaspect { get; set; } = "Set the aspect of a single pixel of your monitor or TV screen (default: 1). A value of 1 means square pixels (correct for (almost?) all LCDs). See also --monitoraspect and --video-aspect-override.";
        public string SchemaLabel_Mpv_msg_level { get; set; } = "Log verbosity";
        public string SchemaDesc_Mpv_msg_level { get; set; } = "Control verbosity directly for each module. The all module changes the verbosity of all the modules. The verbosity changes from this option are applied in order from left to right, and each item can override a previous one.";
        public string SchemaLabel_Mpv_mute { get; set; } = "Start muted";
        public string SchemaDesc_Mpv_mute { get; set; } = "Set startup audio mute status (default: no).";
        public string SchemaLabel_Mpv_native_keyrepeat { get; set; } = "System key repeat";
        public string SchemaDesc_Mpv_native_keyrepeat { get; set; } = "Use system settings for keyrepeat delay and rate, instead of --input-ar-delay and --input-ar-rate (default: no). Whether this applies depends on the VO backend and how it handles keyboard input. Does not apply to terminal input.";
        public string SchemaLabel_Mpv_native_touch { get; set; } = "Native touch events";
        public string SchemaDesc_Mpv_native_touch { get; set; } = "(Windows only) For platforms which send emulated mouse inputs for touch-unaware clients, such as Windows, use system native touch events, instead of receiving them as emulated mouse events (default: no). This is required for multi-touch support for these platforms.";
        public string SchemaLabel_Mpv_oac { get; set; } = "Output audio codec";
        public string SchemaDesc_Mpv_oac { get; set; } = "Specifies the output audio codec. See --oac=help for a full list of supported codecs.";
        public string SchemaLabel_Mpv_oacopts { get; set; } = "Output audio codec options";
        public string SchemaDesc_Mpv_oacopts { get; set; } = "Specifies the output audio codec options for libavcodec. See --oacopts=help for a full list of supported options.";
        public string SchemaLabel_Mpv_ocopy_metadata { get; set; } = "Copy metadata";
        public string SchemaDesc_Mpv_ocopy_metadata { get; set; } = "Copy metadata from input files to output files when encoding (default: yes).";
        public string SchemaLabel_Mpv_of { get; set; } = "Output container format";
        public string SchemaDesc_Mpv_of { get; set; } = "Specifies the output format (overrides autodetection by the file name extension of the file specified by --o). See --of=help for a full list of supported formats.";
        public string SchemaLabel_Mpv_ofopts { get; set; } = "Output container options";
        public string SchemaDesc_Mpv_ofopts { get; set; } = "Specifies the output format options for libavformat. See --ofopts=help for a full list of supported options.";
        public string SchemaLabel_Mpv_orawts { get; set; } = "Pass through timestamps";
        public string SchemaDesc_Mpv_orawts { get; set; } = "Copies input pts to the output video (not supported by some output container formats, e.g. AVI). In this mode, discontinuities are not fixed and all pts are passed through as-is. Never seek backwards or use multiple input files in this mode!";
        public string SchemaLabel_Mpv_ordered_chapters { get; set; } = "Ordered chapters";
        public string SchemaDesc_Mpv_ordered_chapters { get; set; } = "Enable support for Matroska ordered chapters. mpv will load and search for video segments from other files, and will also respect any chapter order specified for the main file (default: yes).";
        public string SchemaLabel_Mpv_ordered_chapters_files { get; set; } = "Ordered chapter references";
        public string SchemaDesc_Mpv_ordered_chapters_files { get; set; } = "Loads the given file as playlist, and tries to use the files contained in it as reference files when opening a Matroska file that uses ordered chapters. This overrides the normal mechanism for loading referenced files by scanning the same directory the main file is located in.";
        public string SchemaLabel_Mpv_oremove_metadata { get; set; } = "Exclude metadata";
        public string SchemaDesc_Mpv_oremove_metadata { get; set; } = "Specifies metadata to exclude from the output file when copying from the input file.";
        public string SchemaLabel_Mpv_osc { get; set; } = "On-screen controller";
        public string SchemaDesc_Mpv_osc { get; set; } = "Whether to load the on-screen-controller (default: yes).";
        public string SchemaLabel_Mpv_osd_bar { get; set; } = "OSD progress bar";
        public string SchemaDesc_Mpv_osd_bar { get; set; } = "Enable display of the OSD bar (default: yes).";
        public string SchemaLabel_Mpv_osd_bar_align_x { get; set; } = "Progress bar horizontal position";
        public string SchemaDesc_Mpv_osd_bar_align_x { get; set; } = "Position of the OSD bar. -1 is far left, 0 is centered, 1 is far right. Fractional values (like 0.5) are allowed.";
        public string SchemaLabel_Mpv_osd_bar_align_y { get; set; } = "Progress bar vertical position";
        public string SchemaDesc_Mpv_osd_bar_align_y { get; set; } = "Position of the OSD bar. -1 is top, 0 is centered, 1 is bottom. Fractional values (like 0.5) are allowed.";
        public string SchemaLabel_Mpv_osd_bar_marker_min_size { get; set; } = "Marker minimum size";
        public string SchemaDesc_Mpv_osd_bar_marker_min_size { get; set; } = "Minimum OSD bar marker size.";
        public string SchemaLabel_Mpv_osd_bar_marker_scale { get; set; } = "Marker size factor";
        public string SchemaDesc_Mpv_osd_bar_marker_scale { get; set; } = "Factor for the OSD bar marker size relative to the OSD bar outline size.";
        public string SchemaLabel_Mpv_osd_bar_marker_style { get; set; } = "Marker style";
        public string SchemaDesc_Mpv_osd_bar_marker_style { get; set; } = "Set the OSD bar marker style.";
        public string SchemaLabel_Mpv_osd_bar_outline_size { get; set; } = "Progress bar thickness";
        public string SchemaDesc_Mpv_osd_bar_outline_size { get; set; } = "Size of the outline of the OSD bar in scaled pixels (see --sub-font-size for details).";
        public string SchemaLabel_Mpv_osd_bitmap_max_size { get; set; } = "OSD bitmap cache";
        public string SchemaDesc_Mpv_osd_bitmap_max_size { get; set; } = "Set the maximum bitmap cache size in libass cache for the OSD. 0 means libass uses its default value. This accepts values in MB.";
        public string SchemaLabel_Mpv_osd_border_style { get; set; } = "OSD text border style";
        public string SchemaDesc_Mpv_osd_border_style { get; set; } = "See --sub-border-style. Style used for OSD text border.";
        public string SchemaLabel_Mpv_osd_glyph_limit { get; set; } = "OSD glyph cache limit";
        public string SchemaDesc_Mpv_osd_glyph_limit { get; set; } = "Set the maximum number of cached glyphs in libass cache for the OSD. 0 means libass uses its default value.";
        public string SchemaLabel_Mpv_osd_msg1 { get; set; } = "OSD level 1 text";
        public string SchemaDesc_Mpv_osd_msg1 { get; set; } = "Show this string as message on OSD with OSD level 1 (visible by default). The message will be visible by default, and as long as no other message covers it, and the OSD level isn't changed (see --osd-level). Expands properties; see Property Expansion.";
        public string SchemaLabel_Mpv_osd_msg2 { get; set; } = "OSD level 2 text";
        public string SchemaDesc_Mpv_osd_msg2 { get; set; } = "Similar to --osd-msg1, but for OSD level 2. If this is an empty string (default), then the playback time is shown.";
        public string SchemaLabel_Mpv_osd_msg3 { get; set; } = "OSD level 3 text";
        public string SchemaDesc_Mpv_osd_msg3 { get; set; } = "Similar to --osd-msg1, but for OSD level 3. If this is an empty string (default), then the playback time, duration, and some more information is shown.";
        public string SchemaLabel_Mpv_osd_playlist_entry { get; set; } = "Playlist entry label";
        public string SchemaDesc_Mpv_osd_playlist_entry { get; set; } = "Whether to display the media title, filename, or both. If the media-title is not available, it will display only the filename.";
        public string SchemaLabel_Mpv_osd_prune_delay { get; set; } = "OSD event prune delay";
        public string SchemaDesc_Mpv_osd_prune_delay { get; set; } = "Set the delay for automatic pruning of events from memory in libass. Disabled by default. See also --sub-ass-prune-delay.";
        public string SchemaLabel_Mpv_osd_status_msg { get; set; } = "Custom status text";
        public string SchemaDesc_Mpv_osd_status_msg { get; set; } = "Show a custom string during playback instead of the standard status text. This overrides the status text used for --osd-level=3, when using the show-progress command (by default mapped to P), and when seeking if enabled with --osd-on-seek or osd- prefixes in input.conf (see Input Command Prefixes). Expands properties. See Property Expansion.";
        public string SchemaLabel_Mpv_oset_metadata { get; set; } = "Set metadata";
        public string SchemaDesc_Mpv_oset_metadata { get; set; } = "Specifies metadata to include in the output file. Supported keys vary between output formats. For example, Matroska (MKV) and FLAC allow almost arbitrary keys, while support in MP4 and MP3 is more limited.";
        public string SchemaLabel_Mpv_ovc { get; set; } = "Output video codec";
        public string SchemaDesc_Mpv_ovc { get; set; } = "Specifies the output video codec. See --ovc=help for a full list of supported codecs.";
        public string SchemaLabel_Mpv_ovcopts { get; set; } = "Output video codec options";
        public string SchemaDesc_Mpv_ovcopts { get; set; } = "Specifies the output video codec options for libavcodec. See --ovcopts=help for a full list of supported options.";
        public string SchemaLabel_Mpv_pause { get; set; } = "Start paused";
        public string SchemaDesc_Mpv_pause { get; set; } = "Start the player in paused state.";
        public string SchemaLabel_Mpv_pitch { get; set; } = "Audio pitch";
        public string SchemaDesc_Mpv_pitch { get; set; } = "Raise or lower the audio's pitch by the factor given as parameter. Does not affect playback speed. Playing with an altered pitch automatically inserts the scaletempo2 audio filter.";
        public string SchemaLabel_Mpv_play_direction { get; set; } = "Playback direction";
        public string SchemaDesc_Mpv_play_direction { get; set; } = "Control the playback direction (default: forward). Setting backward will attempt to play the file in reverse direction, with decreasing playback time. If this is set on playback start, playback will start from the end of the file. If this is changed during playback, a hr-seek will be issued to change the direction.";
        public string SchemaLabel_Mpv_player_operation_mode { get; set; } = "Player mode";
        public string SchemaDesc_Mpv_player_operation_mode { get; set; } = "For enabling \"pseudo GUI mode\", which means that the defaults for some options are changed. This option should not normally be used directly, but only by mpv internally, or mpv-provided scripts, config files, or .desktop files. See PSEUDO GUI MODE for details.";
        public string SchemaLabel_Mpv_playlist_exts { get; set; } = "Playlist extensions";
        public string SchemaDesc_Mpv_playlist_exts { get; set; } = "Playlist file extensions to try to match when using --autocreate-playlist or --directory-filter-types.";
        public string SchemaLabel_Mpv_playlist_inherit_options { get; set; } = "Inherit playlist options";
        public string SchemaDesc_Mpv_playlist_inherit_options { get; set; } = "Whether the per-file options of a playlist file are inherited by its items when the playlist file is resolved and expanded (default: no). The value current means that for playlists created by --autocreate-playlist, only the file from which the playlist is created inherits the options.";
        public string SchemaLabel_Mpv_playlist_start { get; set; } = "Starting playlist entry";
        public string SchemaDesc_Mpv_playlist_start { get; set; } = "Set which file on the internal playlist to start playback with. The index is an integer, with 0 meaning the first file. The value auto means that the selection of the entry to play is left to the playback resume mechanism (default). If an entry with the given index doesn't exist, the behavior is unspecified and might change in future mpv versions. The same applies if the playlist contains further playlists (don't expect any reasonable behavior). Passing a playlist file to mpv should work with this option, though. E.g. mpv playlist.m3u --playlist-start=123 will work as expected, as long as playlist.m3u does not link to further playlists.";
        public string SchemaLabel_Mpv_priority { get; set; } = "Process priority";
        public string SchemaDesc_Mpv_priority { get; set; } = "(Windows only) Set process priority for mpv according to the predefined priorities available under Windows.";
        public string SchemaLabel_Mpv_profile { get; set; } = "Profiles";
        public string SchemaDesc_Mpv_profile { get; set; } = "Use the given profile(s), --profile=help displays a list of the defined profiles.";
        public string SchemaLabel_Mpv_rar_list_all_volumes { get; set; } = "List all RAR volumes";
        public string SchemaDesc_Mpv_rar_list_all_volumes { get; set; } = "When opening multi-volume rar files, open all volumes to create a full list of contained files (default: no). If disabled, only the archive entries whose headers are located within the first volume are listed (and thus played when opening a .rar file with mpv). Doing so speeds up opening, and the typical idiotic use-case of playing uncompressed multi-volume rar files that contain a single media file is made faster.";
        public string SchemaLabel_Mpv_rebase_start_time { get; set; } = "Shift start time to zero";
        public string SchemaDesc_Mpv_rebase_start_time { get; set; } = "Whether to move the file start time to 00:00:00 (default: yes). This is less awkward for files which start at a random timestamp, such as transport streams. On the other hand, if there are timestamp resets, the resulting behavior can be rather weird. For this reason, and in case you are actually interested in the real timestamps, this behavior can be disabled with no.";
        public string SchemaLabel_Mpv_replaygain_clip { get; set; } = "Allow clipping";
        public string SchemaDesc_Mpv_replaygain_clip { get; set; } = "Allow the volume gain to clip (default: no). If this option is not enabled, mpv automatically will prevent clipping by lowering the gain.";
        public string SchemaLabel_Mpv_replaygain_fallback { get; set; } = "Fallback gain";
        public string SchemaDesc_Mpv_replaygain_fallback { get; set; } = "Gain in dB to apply if the file has no replay gain tags. This option is always applied if the replaygain logic is somehow inactive. If this is applied, no other replaygain options are applied.";
        public string SchemaLabel_Mpv_replaygain_preamp { get; set; } = "Adjustment gain";
        public string SchemaDesc_Mpv_replaygain_preamp { get; set; } = "Pre-amplification gain in dB to apply to the selected replaygain gain (default: 0).";
        public string SchemaLabel_Mpv_reset_on_next_file { get; set; } = "Reset options per file";
        public string SchemaDesc_Mpv_reset_on_next_file { get; set; } = "Normally, mpv will try to keep all settings when playing the next file on the playlist, even if they were changed by the user during playback. (This behavior is the opposite of MPlayer's, which tries to reset all settings when starting next file.)";
        public string SchemaLabel_Mpv_resume_playback_check_mtime { get; set; } = "Verify file before resuming";
        public string SchemaDesc_Mpv_resume_playback_check_mtime { get; set; } = "Only restore the playback position from the watch_later configuration subdirectory (usually ~/.config/mpv/watch_later/) if the file's modification time is the same as at the time of saving. This may prevent skipping forward in files with the same name which have different content. (Default: no)";
        public string SchemaLabel_Mpv_rtsp_transport { get; set; } = "RTSP transport";
        public string SchemaDesc_Mpv_rtsp_transport { get; set; } = "Select RTSP transport method (default: tcp). This selects the underlying network transport when playing rtsp://... URLs. The value lavf leaves the decision to libavformat.";
        public string SchemaLabel_Mpv_save_watch_history { get; set; } = "Save watch history";
        public string SchemaDesc_Mpv_save_watch_history { get; set; } = "Whether to save which files are played. These can be then selected with the default g-h key binding.";
        public string SchemaLabel_Mpv_scaler_resizes_only { get; set; } = "Scale only when resizing";
        public string SchemaDesc_Mpv_scaler_resizes_only { get; set; } = "Disable the scaler if the video image is not resized. In that case, bilinear is used instead of whatever is set with --scale. Bilinear will reproduce the source image perfectly if no scaling is performed. Enabled by default. Note that this option never affects --cscale.";
        public string SchemaLabel_Mpv_screenshot_avif_opts { get; set; } = "AVIF encoder options";
        public string SchemaDesc_Mpv_screenshot_avif_opts { get; set; } = "Specifies libavcodec options for selected encoder. For more information, consult the FFmpeg documentation.";
        public string SchemaLabel_Mpv_screenshot_avif_pixfmt { get; set; } = "AVIF pixel format";
        public string SchemaDesc_Mpv_screenshot_avif_pixfmt { get; set; } = "Specify the pixel format for the libavcodec encoder. Defaults to empty, which lets mpv pick one close to the source format.";
        public string SchemaLabel_Mpv_screenshot_dir { get; set; } = "Screenshot folder";
        public string SchemaDesc_Mpv_screenshot_dir { get; set; } = "Store screenshots in this directory. This path is joined with the filename generated by --screenshot-template. If the template filename is already absolute, the directory is ignored.";
        public string SchemaLabel_Mpv_script_opts { get; set; } = "Script options";
        public string SchemaDesc_Mpv_script_opts { get; set; } = "Set options for scripts. A script can query an option by key. If an option is used and what semantics the option value has depends entirely on the loaded scripts. Values not claimed by any scripts are ignored.";
        public string SchemaLabel_Mpv_scripts { get; set; } = "Load scripts";
        public string SchemaDesc_Mpv_scripts { get; set; } = "Load a script (Lua or JS) or a C plugin. The second option allows you to load multiple scripts by separating them with the path separator (: on Unix, ; on Windows).";
        public string SchemaLabel_Mpv_sdr_adjust_gamma { get; set; } = "Adjust SDR gamma";
        public string SchemaDesc_Mpv_sdr_adjust_gamma { get; set; } = "SDR transfer functions are often ambiguous or mismatched. Even if files are tagged with a specific function (e.g. bt.709), the actual content may not match. For example, most screen capture software tags its output as bt.709, but the content is usually a direct sRGB capture.";
        public string SchemaLabel_Mpv_secondary_sid { get; set; } = "Secondary subtitle track";
        public string SchemaDesc_Mpv_secondary_sid { get; set; } = "Select a secondary subtitle stream. This is similar to --sid. If a secondary subtitle is selected, it will be rendered as toptitle (i.e. on the top of the screen) alongside the normal subtitle by default, and provides a way to render two subtitles at once.";
        public string SchemaLabel_Mpv_show_dependent_tracks { get; set; } = "Show dependent tracks";
        public string SchemaDesc_Mpv_show_dependent_tracks { get; set; } = "Show dependent tracks in the track list (default: no). Dependent tracks carry coded data that is not independently decodable. For example, the tile sub-streams that make up a tiled HEIF image, the raw coded layers of an IAMF audio element, or the enhancement stream in an LCEVC group. They are hidden by default because exposing them would clutter the track list with entries that cannot be meaningfully selected on their own.";
        public string SchemaLabel_Mpv_show_in_taskbar { get; set; } = "Show in taskbar";
        public string SchemaDesc_Mpv_show_in_taskbar { get; set; } = "(Windows and X11 only) Show mpv in the taskbar (default: yes). If set to no, mpv will no longer appear in taskbars and tasklists in supported window managers, and may be excluded from Alt+Tab window switching.";
        public string SchemaLabel_Mpv_shuffle { get; set; } = "Shuffle playlist";
        public string SchemaDesc_Mpv_shuffle { get; set; } = "Play files in random order. This works by shuffling the playlist at the following points:";
        public string SchemaLabel_Mpv_sid { get; set; } = "Subtitle track";
        public string SchemaDesc_Mpv_sid { get; set; } = "Display the subtitle stream specified by <ID>. auto selects the default, no disables subtitles.";
        public string SchemaLabel_Mpv_snap_window { get; set; } = "Snap to screen edges";
        public string SchemaDesc_Mpv_snap_window { get; set; } = "(Windows only) Snap the player window to screen edges.";
        public string SchemaLabel_Mpv_spirv_compiler { get; set; } = "SPIR-V compiler";
        public string SchemaDesc_Mpv_spirv_compiler { get; set; } = "Controls which compiler is used to translate GLSL to SPIR-V. This is only relevant for --gpu-api=d3d11 with --vo=gpu. The possible choices are currently:";
        public string SchemaLabel_Mpv_sstep { get; set; } = "Frame stepping";
        public string SchemaDesc_Mpv_sstep { get; set; } = "Skip <sec> seconds after every frame.";
        public string SchemaLabel_Mpv_start { get; set; } = "Start position";
        public string SchemaDesc_Mpv_start { get; set; } = "Seek to given time position.";
        public string SchemaLabel_Mpv_stop_playback_on_init_failure { get; set; } = "Stop when a track fails";
        public string SchemaDesc_Mpv_stop_playback_on_init_failure { get; set; } = "Stop playback if either audio or video fails to initialize (default: no). With no, playback will continue in video-only or audio-only mode if one of them fails. This doesn't affect playback of audio-only or video-only files.";
        public string SchemaLabel_Mpv_stop_screensaver { get; set; } = "Suppress screensaver";
        public string SchemaDesc_Mpv_stop_screensaver { get; set; } = "Turns off the screensaver (or screen blanker and similar mechanisms) at startup and turns it on again on exit (default: yes). When using yes, the screensaver will re-enable when playback is not active. always will always disable the screensaver. Note that stopping the screensaver is only possible if a video output is available (i.e. there is an open mpv window). This is not supported on all video outputs, platforms, or desktop environments.";
        public string SchemaLabel_Mpv_stream_buffer_size { get; set; } = "Stream byte buffer";
        public string SchemaDesc_Mpv_stream_buffer_size { get; set; } = "Size of the low level stream byte buffer (default: 128KB). This is used as buffer between demuxer and low level I/O (e.g. sockets). Generally, this can be very small, and the main purpose is similar to the internal buffer FILE in the C standard library will have.";
        public string SchemaLabel_Mpv_stream_dump { get; set; } = "Dump stream to file";
        public string SchemaDesc_Mpv_stream_dump { get; set; } = "Instead of playing a file, read its byte stream and write it to the given destination file. The destination is overwritten. Can be useful to test network-related behavior.";
        public string SchemaLabel_Mpv_stream_record { get; set; } = "Record stream";
        public string SchemaDesc_Mpv_stream_record { get; set; } = "Write received/read data from the demuxer to the given output file. The output file will always be overwritten without asking. The output format is determined by the extension of the output file.";
        public string SchemaLabel_Mpv_stretch_dvd_subs { get; set; } = "Stretch DVD subtitles";
        public string SchemaDesc_Mpv_stretch_dvd_subs { get; set; } = "Stretch DVD subtitles when playing anamorphic videos for better looking fonts on badly mastered DVDs. This switch has no effect when the video is stored with square pixels - which for DVD input cannot be the case though.";
        public string SchemaLabel_Mpv_sub_ass { get; set; } = "Native ASS rendering";
        public string SchemaDesc_Mpv_sub_ass { get; set; } = "Render ASS subtitles natively (default: yes).";
        public string SchemaLabel_Mpv_sub_ass_styles { get; set; } = "Extra ASS styles";
        public string SchemaDesc_Mpv_sub_ass_styles { get; set; } = "Load all SSA/ASS styles found in the specified file and use them for rendering text subtitles. The syntax of the file is exactly like the [V4 Styles] / [V4+ Styles] section of SSA/ASS.";
        public string SchemaLabel_Mpv_sub_auto_exts { get; set; } = "Auto-load extensions";
        public string SchemaDesc_Mpv_sub_auto_exts { get; set; } = "Subtitle extensions to try and match when using --sub-auto. Note that modifying this list will also affect what mpv recognizes as subtitles when using drag and drop.";
        public string SchemaLabel_Mpv_sub_border_style { get; set; } = "Border style";
        public string SchemaDesc_Mpv_sub_border_style { get; set; } = "The style of the border.";
        public string SchemaLabel_Mpv_sub_create_cc_track { get; set; } = "Always create CC track";
        public string SchemaDesc_Mpv_sub_create_cc_track { get; set; } = "For every video stream, create a closed captions track (default: no). The only purpose is to make the track available for selection at the start of playback, instead of creating it lazily. This applies only to ATSC A53 Part 4 Closed Captions (displayed by mpv as subtitle tracks using the codec eia_608). The CC track is marked \"default\" and selected according to the normal subtitle track selection rules. You can then use --sid to explicitly select the correct track too.";
        public string SchemaLabel_Mpv_sub_demuxer { get; set; } = "Subtitle demuxer";
        public string SchemaDesc_Mpv_sub_demuxer { get; set; } = "Force subtitle demuxer type for --sub-file. Give the demuxer name as printed by --sub-demuxer=help.";
        public string SchemaLabel_Mpv_sub_files { get; set; } = "External subtitles";
        public string SchemaDesc_Mpv_sub_files { get; set; } = "Add a subtitle file to the list of external subtitles.";
        public string SchemaLabel_Mpv_sub_filter_jsre { get; set; } = "JS subtitle filter";
        public string SchemaDesc_Mpv_sub_filter_jsre { get; set; } = "String list";
        public string SchemaLabel_Mpv_sub_filter_regex { get; set; } = "Regex subtitle filters";
        public string SchemaDesc_Mpv_sub_filter_regex { get; set; } = "String list";
        public string SchemaLabel_Mpv_sub_filter_regex_enable { get; set; } = "Enable regex filtering";
        public string SchemaDesc_Mpv_sub_filter_regex_enable { get; set; } = "Whether to enable regex filtering (default: yes). Note that if no regexes are added to the --sub-filter-regex list, setting this option to yes has no effect. It's meant to easily disable or enable filtering temporarily.";
        public string SchemaLabel_Mpv_sub_filter_regex_plain { get; set; } = "Plain text before regex";
        public string SchemaDesc_Mpv_sub_filter_regex_plain { get; set; } = "Whether to first convert the ASS \"Text\" field to plain-text (default: no). This strips ASS tags and applies ASS directives, like \\N to new-line. If the result is multi-line then the regexp anchors ^ and $ match each line, but still any match discards all lines.";
        public string SchemaLabel_Mpv_sub_filter_regex_warn { get; set; } = "Warn on dropped lines";
        public string SchemaDesc_Mpv_sub_filter_regex_warn { get; set; } = "Log dropped lines with warning log level, instead of verbose (default: no). Helpful for testing.";
        public string SchemaLabel_Mpv_sub_fix_timing_keep { get; set; } = "Timing fix floor";
        public string SchemaDesc_Mpv_sub_fix_timing_keep { get; set; } = "Set the minimum duration in milliseconds for subtitle events to be considered for timing fixes (default: 400). If a subtitle event has a duration smaller than this, its timing is not changed.";
        public string SchemaLabel_Mpv_sub_fps { get; set; } = "Subtitle frame rate";
        public string SchemaDesc_Mpv_sub_fps { get; set; } = "Specify the framerate of the subtitle file (default: video fps). Affects text subtitles only.";
        public string SchemaLabel_Mpv_sub_glyph_limit { get; set; } = "Glyph cache limit";
        public string SchemaDesc_Mpv_sub_glyph_limit { get; set; } = "Set the maximum number of cached glyphs in libass cache for the subtitle track. 0 means libass uses its default value.";
        public string SchemaLabel_Mpv_sub_gray { get; set; } = "Grayscale image subtitles";
        public string SchemaDesc_Mpv_sub_gray { get; set; } = "Convert image subtitles to grayscale. Can help to make yellow DVD/Vobsubs look nicer.";
        public string SchemaLabel_Mpv_sub_past_video_end { get; set; } = "Subtitles past video end";
        public string SchemaDesc_Mpv_sub_past_video_end { get; set; } = "After the last frame of video, if this option is enabled, subtitles will continue to update based on audio timestamps. Otherwise, the subtitles for the last video frame will stay onscreen.";
        public string SchemaLabel_Mpv_sub_scale_with_window { get; set; } = "Scale with window";
        public string SchemaDesc_Mpv_sub_scale_with_window { get; set; } = "Make the subtitle font size relative to the window (default: yes). If this is disabled while --sub-scale-by-window is set to yes, the subtitle font size is scaled relative to the video size instead.";
        public string SchemaLabel_Mpv_sub_speed { get; set; } = "Subtitle speed factor";
        public string SchemaDesc_Mpv_sub_speed { get; set; } = "Multiply the subtitle event timestamps with the given value. Can be used to fix the playback speed for frame-based subtitle formats. Affects text subtitles only.";
        public string SchemaLabel_Mpv_sub_stretch_durations { get; set; } = "Stretch durations";
        public string SchemaDesc_Mpv_sub_stretch_durations { get; set; } = "Stretch a subtitle duration so it ends when the next one starts. Should help with subtitles which erroneously have zero durations.";
        public string SchemaLabel_Mpv_sub_vsfilter_bidi_compat { get; set; } = "VSFilter bidi compat";
        public string SchemaDesc_Mpv_sub_vsfilter_bidi_compat { get; set; } = "Set implicit bidi detection to ltr instead of auto to match ASS' default. This also disables libass' incompatible extensions. This currently includes bracket pair matching according to the revised Unicode Bidirectional Algorithm introduced in Unicode 6.3, and also affects how BiDi runs are split and processed, as well as soft linewrapping of Unicode text.";
        public string SchemaLabel_Mpv_swapchain_depth { get; set; } = "Frame latency";
        public string SchemaDesc_Mpv_swapchain_depth { get; set; } = "Allow up to N in-flight frames. This essentially controls the frame latency. Increasing the swapchain depth can improve pipelining and prevent missed vsyncs, but increases visible latency. This option only mandates an upper limit, the implementation can use a lower latency than requested internally. A setting of 1 means that the VO will wait for every frame to become visible before starting to render the next frame. (Default: 2)";
        public string SchemaLabel_Mpv_target_contrast { get; set; } = "Target display contrast";
        public string SchemaDesc_Mpv_target_contrast { get; set; } = "Specifies the measured contrast of the output display. --target-contrast in conjunction with --target-peak value is used to calculate display black point. Used in black point compensation during HDR tone-mapping. auto is the default and assumes 1000:1 contrast as a typical SDR display would have or an infinite contrast when HDR --target-trc is used. If supported by the API, display contrast will be used as reported. inf contrast specifies display with perfect black level, in practice OLED. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_target_lut { get; set; } = "Output LUT file";
        public string SchemaDesc_Mpv_target_lut { get; set; } = "Specifies a custom LUT file (in Adobe .cube format) to apply to the colors before display on-screen. This LUT is fed values in normalized RGB, after encoding into the target colorspace, so after the application of --target-trc. (Only for --vo=gpu-next)";
        public string SchemaLabel_Mpv_taskbar_progress { get; set; } = "Taskbar progress";
        public string SchemaDesc_Mpv_taskbar_progress { get; set; } = "(Windows only) Enable/disable playback progress rendering in taskbar (Windows 7 and above).";
        public string SchemaLabel_Mpv_teletext_page { get; set; } = "Teletext page";
        public string SchemaDesc_Mpv_teletext_page { get; set; } = "Select a teletext page number to decode.";
        public string SchemaLabel_Mpv_temporal_dither { get; set; } = "Temporal dithering";
        public string SchemaDesc_Mpv_temporal_dither { get; set; } = "Enable temporal dithering. (Only active if dithering is enabled in general.) This changes between 8 different dithering patterns on each frame by changing the orientation of the tiled dithering matrix. Unfortunately, this can lead to flicker on LCD displays, since these have a high reaction time.";
        public string SchemaLabel_Mpv_temporal_dither_period { get; set; } = "Dither update interval";
        public string SchemaDesc_Mpv_temporal_dither_period { get; set; } = "Determines how often the dithering pattern is updated when --temporal-dither is in use. 1 (the default) will update on every video frame, 2 on every other frame, etc.";
        public string SchemaLabel_Mpv_title { get; set; } = "Window title";
        public string SchemaDesc_Mpv_title { get; set; } = "Set the window title. This is used for the video window, and if possible, also sets the audio stream title.";
        public string SchemaLabel_Mpv_tls_ca_file { get; set; } = "TLS CA file";
        public string SchemaDesc_Mpv_tls_ca_file { get; set; } = "Certificate authority database file for use with TLS. (Silently fails with older FFmpeg versions.)";
        public string SchemaLabel_Mpv_tls_cert_file { get; set; } = "TLS client certificate";
        public string SchemaDesc_Mpv_tls_cert_file { get; set; } = "A file containing a certificate to use in the handshake with the peer.";
        public string SchemaLabel_Mpv_tls_key_file { get; set; } = "TLS private key";
        public string SchemaDesc_Mpv_tls_key_file { get; set; } = "A file containing the private key for the certificate.";
        public string SchemaLabel_Mpv_tone_mapping_param { get; set; } = "Tone mapping parameter";
        public string SchemaDesc_Mpv_tone_mapping_param { get; set; } = "Set tone mapping parameters. By default, this is set to the special string default, which maps to an algorithm-specific default value. Ignored if the tone mapping algorithm is not tunable. This affects the following tone mapping algorithms:";
        public string SchemaLabel_Mpv_track_auto_selection { get; set; } = "Automatic track selection";
        public string SchemaDesc_Mpv_track_auto_selection { get; set; } = "Enable the default track auto-selection (default: yes). Enabling this will make the player select streams according to --aid, --alang, and others. If it is disabled, no tracks are selected. In addition, the player will not exit if no tracks are selected, and wait instead (this wait mode is similar to pausing, but the pause option is not set).";
        public string SchemaLabel_Mpv_treat_srgb_as_power22 { get; set; } = "Treat sRGB as power 2.2";
        public string SchemaDesc_Mpv_treat_srgb_as_power22 { get; set; } = "When enabled, sRGB is (de)linearized using a pure power 2.2 curve instead of the standard sRGB piecewise transfer function.";
        public string SchemaLabel_Mpv_untimed { get; set; } = "Unlimited frame rate";
        public string SchemaDesc_Mpv_untimed { get; set; } = "Do not sleep when outputting video frames. Useful for benchmarks when used with --audio=no.";
        public string SchemaLabel_Mpv_use_embedded_icc_profile { get; set; } = "Use embedded colour profile";
        public string SchemaDesc_Mpv_use_embedded_icc_profile { get; set; } = "Load the embedded ICC profile contained in media files such as PNG images. (Default: yes). Note that this option only works when also using a display ICC profile (--icc-profile or --icc-profile-auto), and also requires LittleCMS 2 support.";
        public string SchemaLabel_Mpv_use_filedir_conf { get; set; } = "Per-directory config";
        public string SchemaDesc_Mpv_use_filedir_conf { get; set; } = "Look for a file-specific configuration file in the same directory as the file that is being played. See File-specific Configuration Files.";
        public string SchemaLabel_Mpv_vd_apply_cropping { get; set; } = "Apply codec cropping";
        public string SchemaDesc_Mpv_vd_apply_cropping { get; set; } = "Certain video codecs support cropping, meaning that only a sub-rectangle of the decoded frame is intended for display. This option controls how cropping is handled by libavcodec. Cropping during decoding has certain limitations with regards to alignment and hardware decoding. If this option is enabled, decoder will apply the crop, else VO will handle it. Enabled by default.";
        public string SchemaLabel_Mpv_vd_lavc_assume_old_x264 { get; set; } = "Assume old x264";
        public string SchemaDesc_Mpv_vd_lavc_assume_old_x264 { get; set; } = "Assume the video was encoded by an old, buggy x264 version (default: no). Normally, this is autodetected by libavcodec. But if the bitstream contains no x264 version info (or it was somehow skipped), and the stream was in fact encoded by an old x264 version (build 150 or earlier), and if the stream uses 4:4:4 chroma, then libavcodec will by default show corrupted video. This option sets the libavcodec x264_build option to 150, which means that if the stream contains no version info, or was not encoded by x264 at all, it assumes it was encoded by the old version. Enabling this option is pretty safe if you want your broken files to work, but in theory this can break on streams not encoded by x264, or if a stream encoded by a newer x264 version contains no version info.";
        public string SchemaLabel_Mpv_vd_lavc_bitexact { get; set; } = "Bit-exact decoding";
        public string SchemaDesc_Mpv_vd_lavc_bitexact { get; set; } = "Only use bit-exact algorithms in all decoding steps (for codec testing).";
        public string SchemaLabel_Mpv_vd_lavc_check_hw_profile { get; set; } = "Check decoder profile";
        public string SchemaDesc_Mpv_vd_lavc_check_hw_profile { get; set; } = "Check hardware decoder profile (default: yes). If no is set, the highest profile of the hardware decoder is unconditionally selected, and decoding is forced even if the profile of the video is higher than that. The result is most likely broken decoding, but may also help if the detected or reported profiles are somehow incorrect.";
        public string SchemaLabel_Mpv_vd_lavc_fast { get; set; } = "Non-spec optimizations";
        public string SchemaDesc_Mpv_vd_lavc_fast { get; set; } = "Enable optimizations which do not comply with the format specification and potentially cause problems, like simpler dequantization, simpler motion compensation, assuming use of the default quantization matrix, assuming YUV 4:2:0 and skipping a few checks to detect damaged bitstreams.";
        public string SchemaLabel_Mpv_vd_lavc_film_grain { get; set; } = "GPU film grain";
        public string SchemaDesc_Mpv_vd_lavc_film_grain { get; set; } = "Enables film grain application on the GPU. If video decoding is done on the CPU, doing film grain application on the GPU can speed up decoding. This option can also help hardware decoding, as it can reduce the number of frame copies done.";
        public string SchemaLabel_Mpv_vd_lavc_framedrop { get; set; } = "Decoder frame dropping";
        public string SchemaDesc_Mpv_vd_lavc_framedrop { get; set; } = "Set framedropping mode used with --framedrop (see skiploopfilter for available skip values).";
        public string SchemaLabel_Mpv_vd_lavc_show_all { get; set; } = "Show corrupt frames";
        public string SchemaDesc_Mpv_vd_lavc_show_all { get; set; } = "Show even broken/corrupt frames (default: no). If this option is set to no, libavcodec won't output frames that were either decoded before an initial keyframe was decoded, or frames that are recognized as corrupted.";
        public string SchemaLabel_Mpv_vd_lavc_skipframe { get; set; } = "Skip frames";
        public string SchemaDesc_Mpv_vd_lavc_skipframe { get; set; } = "Skips decoding of frames completely. Big speedup, but jerky motion and sometimes bad artifacts (see skiploopfilter for available skip values).";
        public string SchemaLabel_Mpv_vd_lavc_skipidct { get; set; } = "Skip IDCT";
        public string SchemaDesc_Mpv_vd_lavc_skipidct { get; set; } = "Skips the IDCT step. This degrades quality a lot in almost all cases (see skiploopfilter for available skip values).";
        public string SchemaLabel_Mpv_vd_lavc_skiploopfilter { get; set; } = "Skip loop filter";
        public string SchemaDesc_Mpv_vd_lavc_skiploopfilter { get; set; } = "Skips the loop filter (AKA deblocking) during decoding. Since the filtered frame is supposed to be used as reference for decoding dependent frames, this has a worse effect on quality than not doing deblocking on e.g. MPEG-2 video. But at least for high bitrate HDTV, this provides a big speedup with little visible quality loss. Codecs other than H.264 or HEVC may have partial support for this option (often only all and none).";
        public string SchemaLabel_Mpv_vd_lavc_threads { get; set; } = "Decoder threads";
        public string SchemaDesc_Mpv_vd_lavc_threads { get; set; } = "Number of threads to use for decoding. Whether threading is actually supported depends on codec (default: 0). 0 means autodetect number of cores on the machine and use that, up to the maximum of 16. You can set more than 16 threads manually.";
        public string SchemaLabel_Mpv_vd_queue_enable { get; set; } = "Threaded decoding";
        public string SchemaDesc_Mpv_vd_queue_enable { get; set; } = "Enable running the video/audio decoder on a separate thread (default: no). If enabled, the decoder is run on a separate thread, and a frame queue is put between decoder and higher level playback logic. The size of the frame queue is defined by the other options below.";
        public string SchemaLabel_Mpv_vd_queue_max_bytes { get; set; } = "Queue limit, bytes";
        public string SchemaDesc_Mpv_vd_queue_max_bytes { get; set; } = "Maximum approximate allowed size of the queue. If exceeded, decoding will be stopped. The maximum size can be exceeded by about 1 frame.";
        public string SchemaLabel_Mpv_vd_queue_max_samples { get; set; } = "Queue limit, samples";
        public string SchemaDesc_Mpv_vd_queue_max_samples { get; set; } = "Maximum number of frames (video) or samples (audio) of the queue. The audio size may be exceeded by about 1 frame.";
        public string SchemaLabel_Mpv_vd_queue_max_secs { get; set; } = "Queue limit, seconds";
        public string SchemaDesc_Mpv_vd_queue_max_secs { get; set; } = "Maximum number of seconds of media in the queue. The special value 0 means no limit is set. The queue size may be exceeded by about 2 frames. Timestamp resets may lead to random queue size usage.";
        public string SchemaLabel_Mpv_vid { get; set; } = "Video track";
        public string SchemaDesc_Mpv_vid { get; set; } = "Select video channel. auto selects the default, no disables video.";
        public string SchemaLabel_Mpv_video_aspect_method { get; set; } = "Aspect determination";
        public string SchemaDesc_Mpv_video_aspect_method { get; set; } = "This sets the default video aspect determination method (if the aspect is _not_ overridden by the user with --video-aspect-override or others).";
        public string SchemaLabel_Mpv_video_crop { get; set; } = "Video crop";
        public string SchemaDesc_Mpv_video_crop { get; set; } = "Crop the video by starting at the x, y offset for w, h pixels. The crop is applied to the source video rectangle (before anamorphic stretch) by the VO. A crop rectangle that is not within the video rectangle will be ignored. This works with hwdec, unlike the equivalent 'lavfi-crop'. When offset is omitted, the central area will be cropped. Setting the crop to empty one --video-crop=0x0+0+0 overrides container crop and disables cropping. Setting the crop to --video-crop=\"\" disables manual cropping and restores the container crop if it's specified.";
        public string SchemaLabel_Mpv_video_latency_hacks { get; set; } = "Latency hacks";
        public string SchemaDesc_Mpv_video_latency_hacks { get; set; } = "Enable some things which tend to reduce video latency by 1 or 2 frames (default: no). Note that this option might be removed without notice once the player's timing code does not inherently need to do these things anymore. Using this option is known to break other options such as interpolation, so it is not recommended to enable this.";
        public string SchemaLabel_Mpv_video_margin_ratio_bottom { get; set; } = "Video margin, bottom";
        public string SchemaDesc_Mpv_video_margin_ratio_bottom { get; set; } = "Set extra video margins on each border (default: 0). Each value is a ratio of the window size, using a range 0.0-1.0. For example, setting the option --video-margin-ratio-right=0.2 at a window size of 1000 pixels will add a 200 pixels border on the right side of the window.";
        public string SchemaLabel_Mpv_video_margin_ratio_left { get; set; } = "Video margin, left";
        public string SchemaDesc_Mpv_video_margin_ratio_left { get; set; } = "Set extra video margins on each border (default: 0). Each value is a ratio of the window size, using a range 0.0-1.0. For example, setting the option --video-margin-ratio-right=0.2 at a window size of 1000 pixels will add a 200 pixels border on the right side of the window.";
        public string SchemaLabel_Mpv_video_margin_ratio_right { get; set; } = "Video margin, right";
        public string SchemaDesc_Mpv_video_margin_ratio_right { get; set; } = "Set extra video margins on each border (default: 0). Each value is a ratio of the window size, using a range 0.0-1.0. For example, setting the option --video-margin-ratio-right=0.2 at a window size of 1000 pixels will add a 200 pixels border on the right side of the window.";
        public string SchemaLabel_Mpv_video_margin_ratio_top { get; set; } = "Video margin, top";
        public string SchemaDesc_Mpv_video_margin_ratio_top { get; set; } = "Set extra video margins on each border (default: 0). Each value is a ratio of the window size, using a range 0.0-1.0. For example, setting the option --video-margin-ratio-right=0.2 at a window size of 1000 pixels will add a 200 pixels border on the right side of the window.";
        public string SchemaLabel_Mpv_video_osd { get; set; } = "OSD on video";
        public string SchemaDesc_Mpv_video_osd { get; set; } = "Enabled OSD rendering on the video window (default: yes). This can be used in situations where terminal OSD is preferred. If you just want to disable all OSD rendering, use --osd-level=0.";
        public string SchemaLabel_Mpv_video_recenter { get; set; } = "Recenter small video";
        public string SchemaDesc_Mpv_video_recenter { get; set; } = "Whether to behave as if --video-align-x and --video-align-y were 0 when the video becomes smaller than the window in the respective direction";
        public string SchemaLabel_Mpv_video_scale_x { get; set; } = "Display scale, horizontal";
        public string SchemaDesc_Mpv_video_scale_x { get; set; } = "Multiply the video display size with the given value (default: 1.0). If a non-default value is used, this will be different from the window size, so video will be either cut off, or black bars are added.";
        public string SchemaLabel_Mpv_video_scale_y { get; set; } = "Display scale, vertical";
        public string SchemaDesc_Mpv_video_scale_y { get; set; } = "Multiply the video display size with the given value (default: 1.0). If a non-default value is used, this will be different from the window size, so video will be either cut off, or black bars are added.";
        public string SchemaLabel_Mpv_video_sync_max_audio_change { get; set; } = "Max audio speed change";
        public string SchemaDesc_Mpv_video_sync_max_audio_change { get; set; } = "Maximum additional speed difference in percent that is applied to audio with --video-sync=display-... (default: 0.125). Normally, the player plays the audio at the speed of the video. But if the difference between audio and video position is too high, e.g. due to drift or other timing errors, it will attempt to speed up or slow down audio by this additional factor. Too low values could lead to video frame dropping or repeating if the A/V desync cannot be compensated, too high values could lead to chaotic frame dropping due to the audio \"overshooting\" and skipping multiple video frames before the sync logic can react.";
        public string SchemaLabel_Mpv_video_sync_max_factor { get; set; } = "Max FPS sync factor";
        public string SchemaDesc_Mpv_video_sync_max_factor { get; set; } = "Maximum multiple for which to try to fit the video's FPS to the display's FPS (default: 5).";
        public string SchemaLabel_Mpv_video_timing_offset { get; set; } = "Render lead time";
        public string SchemaDesc_Mpv_video_timing_offset { get; set; } = "Control how long before video display target time the frame should be rendered (default: 0.050). If a video frame should be displayed at a certain time, the VO will start rendering the frame earlier, and then will perform a blocking wait until the display time, and only then \"swap\" the frame to display. The rendering cannot start before the previous frame is displayed, so this value is implicitly limited by the video framerate. With normal video frame rates, the default value will ensure that rendering is always immediately started after the previous frame was displayed. On the other hand, setting a too high value can reduce responsiveness with low FPS value.";
        public string SchemaLabel_Mpv_vlang { get; set; } = "Preferred video language";
        public string SchemaDesc_Mpv_vlang { get; set; } = "Analogous to --alang and --slang, for video tracks.";
        public string SchemaLabel_Mpv_vo_direct3d_disable_texture_align { get; set; } = "Disable texture alignment";
        public string SchemaDesc_Mpv_vo_direct3d_disable_texture_align { get; set; } = "Flag; Default: no";
        public string SchemaLabel_Mpv_vo_direct3d_exact_backbuffer { get; set; } = "Exact backbuffer size";
        public string SchemaDesc_Mpv_vo_direct3d_exact_backbuffer { get; set; } = "Always resize the backbuffer to window size.";
        public string SchemaLabel_Mpv_vo_direct3d_force_power_of_2 { get; set; } = "Force power-of-2 textures";
        public string SchemaDesc_Mpv_vo_direct3d_force_power_of_2 { get; set; } = "Always force textures to power of 2, even if the device reports non-power-of-2 texture sizes as supported.";
        public string SchemaLabel_Mpv_vo_direct3d_swap_discard { get; set; } = "Discard swap effect";
        public string SchemaDesc_Mpv_vo_direct3d_swap_discard { get; set; } = "Use D3DSWAPEFFECT_DISCARD, which might be faster. Might be slower too, as it must(?) clear every frame.";
        public string SchemaLabel_Mpv_vo_direct3d_texture_memory { get; set; } = "Texture memory";
        public string SchemaDesc_Mpv_vo_direct3d_texture_memory { get; set; } = "Only affects operation with shaders/texturing enabled, and (E)OSD. Possible values:";
        public string SchemaLabel_Mpv_vo_image_avif_encoder { get; set; } = "AVIF encoder";
        public string SchemaDesc_Mpv_vo_image_avif_encoder { get; set; } = "String; Default: libaom-av1";
        public string SchemaLabel_Mpv_vo_image_avif_opts { get; set; } = "AVIF encoder options";
        public string SchemaDesc_Mpv_vo_image_avif_opts { get; set; } = "Key/value list; Default: usage=allintra,crf=0,cpu-used=8";
        public string SchemaLabel_Mpv_vo_image_avif_pixfmt { get; set; } = "AVIF pixel format";
        public string SchemaDesc_Mpv_vo_image_avif_pixfmt { get; set; } = "String";
        public string SchemaLabel_Mpv_vo_image_format { get; set; } = "Image output format";
        public string SchemaDesc_Mpv_vo_image_format { get; set; } = "One of: jpg, jpeg, png, webp, jxl, avif; Default: jpg";
        public string SchemaLabel_Mpv_vo_image_high_bit_depth { get; set; } = "High bit depth images";
