        public string SchemaLabel_Mpv_window_scale { get; set; } = "Window scale";
        public string SchemaDesc_Mpv_window_scale { get; set; } = "Resize the video window to a multiple (or fraction) of the video size. This option is applied before --autofit and other options are applied (so they override this option). Changing this option while the window is maximized can unmaximize the window depending on the OS and window manager. If the window does not unmaximize, the multiplier will be applied if the user unmaximizes the window later.";
