        public string SchemaLabel_Mpv_ytdl { get; set; } = "youtube-dl integration";
        public string SchemaDesc_Mpv_ytdl { get; set; } = "Enable the youtube-dl hook-script. It will look at the input URL, and will play the video located on the website. This works with many streaming sites, not just the one that the script is named after. This requires a recent version of youtube-dl to be installed on the system (default: yes).";
        public string SchemaLabel_Mpv_ytdl_format { get; set; } = "youtube-dl format";
        public string SchemaDesc_Mpv_ytdl_format { get; set; } = "Format selection string that is directly passed to youtube-dl. The possible values are specific to the website and the video, for a given URL the available formats can be found with the command youtube-dl -F URL. See youtube-dl's documentation for available aliases. (Default: bestvideo*+bestaudio/bestvideo+bestaudio/best)";
        public string SchemaLabel_Mpv_ytdl_raw_options { get; set; } = "youtube-dl extra options";
